# ================================================================
# Free IR 1.0 — Node 구조 정의
# Free IR의 모든 노드를 FreeLang으로 표현
# ================================================================

# ----------------------------------------------------------------
# 1. 타입 표현
# ----------------------------------------------------------------

fn ir_type_i8()   { return { "kind": "primitive", "name": "i8",   "size": 1 } }
fn ir_type_i16()  { return { "kind": "primitive", "name": "i16",  "size": 2 } }
fn ir_type_i32()  { return { "kind": "primitive", "name": "i32",  "size": 4 } }
fn ir_type_i64()  { return { "kind": "primitive", "name": "i64",  "size": 8 } }
fn ir_type_u8()   { return { "kind": "primitive", "name": "u8",   "size": 1 } }
fn ir_type_u16()  { return { "kind": "primitive", "name": "u16",  "size": 2 } }
fn ir_type_u32()  { return { "kind": "primitive", "name": "u32",  "size": 4 } }
fn ir_type_u64()  { return { "kind": "primitive", "name": "u64",  "size": 8 } }
fn ir_type_f32()  { return { "kind": "primitive", "name": "f32",  "size": 4 } }
fn ir_type_f64()  { return { "kind": "primitive", "name": "f64",  "size": 8 } }
fn ir_type_bool() { return { "kind": "primitive", "name": "bool", "size": 1 } }
fn ir_type_void() { return { "kind": "primitive", "name": "void", "size": 0 } }

fn ir_type_ptr(inner_type) {
  return { "kind": "ptr", "inner": inner_type, "size": 8 }
}

fn ir_type_array(elem_type, count) {
  size = elem_type["size"] * count
  return { "kind": "array", "elem": elem_type, "count": count, "size": size }
}

fn ir_type_slice(elem_type) {
  return { "kind": "slice", "elem": elem_type, "size": 16 }
}

fn ir_type_struct(name, fields) {
  # fields = [{ "name": str, "type": IrType }, ...]
  # size 계산 (alignment 포함, Phase 1: 단순 합산)
  size = 0
  i = 0
  while i < len(fields) {
    f = fields[i]
    size = size + f["type"]["size"]
    i = i + 1
  }
  return { "kind": "struct", "name": name, "fields": fields, "size": size }
}

fn ir_type_fn(param_types, ret_type) {
  return { "kind": "fn", "params": param_types, "ret": ret_type, "size": 8 }
}

# ----------------------------------------------------------------
# 2. 값(Value) 표현
# ----------------------------------------------------------------

# SSA 값: %name
fn ir_val_reg(name, ty) {
  return { "kind": "reg", "name": name, "type": ty }
}

# 정수 상수
fn ir_val_int(value, ty) {
  return { "kind": "const_int", "value": value, "type": ty }
}

# 부동소수 상수
fn ir_val_float(value, ty) {
  return { "kind": "const_float", "value": value, "type": ty }
}

# bool 상수
fn ir_val_bool(value) {
  return { "kind": "const_bool", "value": value, "type": ir_type_bool() }
}

# null 포인터
fn ir_val_null(ty) {
  return { "kind": "const_null", "type": ty }
}

# 전역 심볼 참조 @name
fn ir_val_global(name, ty) {
  return { "kind": "global_ref", "name": name, "type": ty }
}

# ----------------------------------------------------------------
# 3. Instruction 표현
# ----------------------------------------------------------------

# --- 산술/논리 ---

fn ir_inst_binop(op, result_name, ty, lhs, rhs) {
  # op: "add","sub","mul","div","rem","and","or","xor","shl","shr"
  #     "fadd","fsub","fmul","fdiv"
  return {
    "kind": "binop",
    "op": op,
    "result": result_name,
    "type": ty,
    "lhs": lhs,
    "rhs": rhs
  }
}

fn ir_inst_neg(result_name, ty, operand) {
  return { "kind": "neg", "result": result_name, "type": ty, "operand": operand }
}

# --- 비교 ---

fn ir_inst_icmp(pred, result_name, ty, lhs, rhs) {
  # pred: "eq","ne","lt","le","gt","ge","ult","ule","ugt","uge"
  return {
    "kind": "icmp",
    "pred": pred,
    "result": result_name,
    "type": ty,
    "lhs": lhs,
    "rhs": rhs
  }
}

fn ir_inst_fcmp(pred, result_name, ty, lhs, rhs) {
  # pred: "oeq","one","olt","ole","ogt","oge"
  return {
    "kind": "fcmp",
    "pred": pred,
    "result": result_name,
    "type": ty,
    "lhs": lhs,
    "rhs": rhs
  }
}

# --- 메모리 ---

fn ir_inst_alloca(result_name, ty) {
  # entry block 전용
  ptr_ty = ir_type_ptr(ty)
  return { "kind": "alloca", "result": result_name, "alloc_type": ty, "type": ptr_ty }
}

fn ir_inst_load(result_name, ty, ptr_val) {
  return { "kind": "load", "result": result_name, "type": ty, "ptr": ptr_val }
}

fn ir_inst_store(ty, val, ptr_val) {
  return { "kind": "store", "type": ty, "val": val, "ptr": ptr_val }
}

fn ir_inst_gep(result_name, elem_ty, ptr_val, idx_val) {
  ptr_ty = ir_type_ptr(elem_ty)
  return {
    "kind": "gep",
    "result": result_name,
    "elem_type": elem_ty,
    "ptr": ptr_val,
    "idx": idx_val,
    "type": ptr_ty
  }
}

# --- 타입 변환 ---

fn ir_inst_cast(op, result_name, from_ty, val, to_ty) {
  # op: "trunc","zext","sext","fpext","fptrunc","fptosi","sitofp","bitcast","ptrtoint","inttoptr"
  return {
    "kind": "cast",
    "op": op,
    "result": result_name,
    "from_type": from_ty,
    "val": val,
    "to_type": to_ty,
    "type": to_ty
  }
}

# --- 함수 호출 ---

fn ir_inst_call(result_name, ret_ty, callee, args) {
  # result_name = "" 이면 void 호출
  return {
    "kind": "call",
    "result": result_name,
    "ret_type": ret_ty,
    "callee": callee,
    "args": args,
    "type": ret_ty
  }
}

# --- 제어 흐름 (Terminator) ---

fn ir_inst_br(target_label) {
  return { "kind": "br", "target": target_label }
}

fn ir_inst_br_cond(cond_val, true_label, false_label) {
  return {
    "kind": "br_cond",
    "cond": cond_val,
    "true_label": true_label,
    "false_label": false_label
  }
}

fn ir_inst_ret(val) {
  return { "kind": "ret", "val": val }
}

fn ir_inst_ret_void() {
  return { "kind": "ret_void" }
}

# --- Phi ---

fn ir_inst_phi(result_name, ty, incoming) {
  # incoming = [{ "val": IrVal, "block": string }, ...]
  return {
    "kind": "phi",
    "result": result_name,
    "type": ty,
    "incoming": incoming
  }
}

# ----------------------------------------------------------------
# 4. Basic Block
# ----------------------------------------------------------------

fn ir_block(label, instructions) {
  # instructions = [IrInst, ...]
  # 마지막 inst는 terminator여야 함
  return { "kind": "block", "label": label, "instructions": instructions }
}

fn ir_block_add_inst(block, inst) {
  new_insts = append(block["instructions"], inst)
  return { "kind": "block", "label": block["label"], "instructions": new_insts }
}

fn ir_block_is_terminated(block) {
  insts = block["instructions"]
  n = len(insts)
  if n == 0 { return false }
  last = insts[n - 1]
  k = last["kind"]
  return k == "br" or k == "br_cond" or k == "ret" or k == "ret_void"
}

# ----------------------------------------------------------------
# 5. 함수 정의
# ----------------------------------------------------------------

fn ir_func(name, params, ret_ty, blocks, is_export) {
  # params = [{ "name": string, "type": IrType }, ...]
  # blocks = [IrBlock, ...]
  return {
    "kind": "function",
    "name": name,
    "params": params,
    "ret_type": ret_ty,
    "blocks": blocks,
    "is_export": is_export
  }
}

fn ir_func_extern(name, param_types, ret_ty, is_variadic) {
  return {
    "kind": "extern_fn",
    "name": name,
    "param_types": param_types,
    "ret_type": ret_ty,
    "is_variadic": is_variadic
  }
}

# ----------------------------------------------------------------
# 6. 전역 변수
# ----------------------------------------------------------------

fn ir_global(name, ty, init_val) {
  return { "kind": "global", "name": name, "type": ty, "init": init_val }
}

# ----------------------------------------------------------------
# 7. 모듈
# ----------------------------------------------------------------

fn ir_module(name) {
  return {
    "kind": "module",
    "name": name,
    "globals": [],
    "externs": [],
    "functions": []
  }
}

fn ir_module_add_global(mod, global_def) {
  new_globals = append(mod["globals"], global_def)
  return {
    "kind": "module",
    "name": mod["name"],
    "globals": new_globals,
    "externs": mod["externs"],
    "functions": mod["functions"]
  }
}

fn ir_module_add_extern(mod, extern_def) {
  new_externs = append(mod["externs"], extern_def)
  return {
    "kind": "module",
    "name": mod["name"],
    "globals": mod["globals"],
    "externs": new_externs,
    "functions": mod["functions"]
  }
}

fn ir_module_add_function(mod, func_def) {
  new_fns = append(mod["functions"], func_def)
  return {
    "kind": "module",
    "name": mod["name"],
    "globals": mod["globals"],
    "externs": mod["externs"],
    "functions": new_fns
  }
}

# ----------------------------------------------------------------
# 8. IR 텍스트 출력 (디버깅용)
# ----------------------------------------------------------------

fn ir_type_to_str(ty) {
  k = ty["kind"]
  if k == "primitive" { return ty["name"] }
  if k == "ptr"       { return "ptr<" + ir_type_to_str(ty["inner"]) + ">" }
  if k == "array"     { return "array<" + ir_type_to_str(ty["elem"]) + "," + str(ty["count"]) + ">" }
  if k == "slice"     { return "slice<" + ir_type_to_str(ty["elem"]) + ">" }
  if k == "struct"    { return "struct." + ty["name"] }
  if k == "fn"        { return "fn_ptr" }
  return "unknown_type"
}

fn ir_val_to_str(val) {
  k = val["kind"]
  if k == "reg"         { return "%" + val["name"] }
  if k == "const_int"   { return str(val["value"]) }
  if k == "const_float" { return str(val["value"]) }
  if k == "const_bool"  {
    if val["value"] { return "true" }
    return "false"
  }
  if k == "const_null"  { return "null" }
  if k == "global_ref"  { return "@" + val["name"] }
  return "?"
}

fn ir_inst_to_str(inst) {
  k = inst["kind"]

  if k == "binop" {
    return "%" + inst["result"] + " = " + inst["op"] + " " +
           ir_type_to_str(inst["type"]) + " " +
           ir_val_to_str(inst["lhs"]) + ", " + ir_val_to_str(inst["rhs"])
  }

  if k == "icmp" or k == "fcmp" {
    return "%" + inst["result"] + " = " + k + " " + inst["pred"] + " " +
           ir_type_to_str(inst["type"]) + " " +
           ir_val_to_str(inst["lhs"]) + ", " + ir_val_to_str(inst["rhs"])
  }

  if k == "alloca" {
    return "%" + inst["result"] + " = alloca " + ir_type_to_str(inst["alloc_type"])
  }

  if k == "load" {
    return "%" + inst["result"] + " = load " +
           ir_type_to_str(inst["type"]) + " " + ir_val_to_str(inst["ptr"])
  }

  if k == "store" {
    return "store " + ir_type_to_str(inst["type"]) + " " +
           ir_val_to_str(inst["val"]) + ", " + ir_val_to_str(inst["ptr"])
  }

  if k == "gep" {
    return "%" + inst["result"] + " = gep " +
           ir_type_to_str(inst["elem_type"]) + " " +
           ir_val_to_str(inst["ptr"]) + ", " + ir_val_to_str(inst["idx"])
  }

  if k == "cast" {
    return "%" + inst["result"] + " = " + inst["op"] + " " +
           ir_type_to_str(inst["from_type"]) + " " +
           ir_val_to_str(inst["val"]) + " to " + ir_type_to_str(inst["to_type"])
  }

  if k == "call" {
    args_str = ""
    i = 0
    args = inst["args"]
    while i < len(args) {
      if i > 0 { args_str = args_str + ", " }
      args_str = args_str + ir_val_to_str(args[i])
      i = i + 1
    }
    if inst["result"] == "" {
      return "call void " + ir_val_to_str(inst["callee"]) + "(" + args_str + ")"
    }
    return "%" + inst["result"] + " = call " +
           ir_type_to_str(inst["ret_type"]) + " " +
           ir_val_to_str(inst["callee"]) + "(" + args_str + ")"
  }

  if k == "br"       { return "br label %" + inst["target"] }
  if k == "br_cond"  {
    return "br bool " + ir_val_to_str(inst["cond"]) +
           ", label %" + inst["true_label"] +
           ", label %" + inst["false_label"]
  }
  if k == "ret"      { return "ret " + ir_val_to_str(inst["val"]) }
  if k == "ret_void" { return "ret void" }

  if k == "phi" {
    incoming_str = ""
    i = 0
    ins = inst["incoming"]
    while i < len(ins) {
      if i > 0 { incoming_str = incoming_str + ", " }
      incoming_str = incoming_str + "[" +
        ir_val_to_str(ins[i]["val"]) + ", %" + ins[i]["block"] + "]"
      i = i + 1
    }
    return "%" + inst["result"] + " = phi " +
           ir_type_to_str(inst["type"]) + " " + incoming_str
  }

  return "# unknown_inst: " + k
}

fn ir_block_to_str(block) {
  result = block["label"] + ":\n"
  insts = block["instructions"]
  i = 0
  while i < len(insts) {
    result = result + "  " + ir_inst_to_str(insts[i]) + "\n"
    i = i + 1
  }
  return result
}

fn ir_func_to_str(func) {
  k = func["kind"]

  if k == "extern_fn" {
    params_str = ""
    i = 0
    pts = func["param_types"]
    while i < len(pts) {
      if i > 0 { params_str = params_str + ", " }
      params_str = params_str + ir_type_to_str(pts[i])
      i = i + 1
    }
    if func["is_variadic"] { params_str = params_str + ", ..." }
    return "extern fn @" + func["name"] + "(" + params_str + ") -> " +
           ir_type_to_str(func["ret_type"])
  }

  prefix = "define fn "
  if func["is_export"] { prefix = "export fn " }

  params_str = ""
  i = 0
  params = func["params"]
  while i < len(params) {
    if i > 0 { params_str = params_str + ", " }
    params_str = params_str + ir_type_to_str(params[i]["type"]) + " %" + params[i]["name"]
    i = i + 1
  }

  header = prefix + "@" + func["name"] + "(" + params_str + ") -> " +
           ir_type_to_str(func["ret_type"]) + " {\n"

  body = ""
  i = 0
  blocks = func["blocks"]
  while i < len(blocks) {
    body = body + ir_block_to_str(blocks[i])
    i = i + 1
  }

  return header + body + "}"
}

fn ir_module_to_str(mod) {
  result = "module @" + mod["name"] + "\n\n"

  # extern 선언
  i = 0
  exts = mod["externs"]
  while i < len(exts) {
    result = result + ir_func_to_str(exts[i]) + "\n"
    i = i + 1
  }

  if len(exts) > 0 { result = result + "\n" }

  # 전역 변수
  i = 0
  globs = mod["globals"]
  while i < len(globs) {
    g = globs[i]
    result = result + "global @" + g["name"] + ": " +
             ir_type_to_str(g["type"]) + "\n"
    i = i + 1
  }

  if len(globs) > 0 { result = result + "\n" }

  # 함수
  i = 0
  fns = mod["functions"]
  while i < len(fns) {
    result = result + ir_func_to_str(fns[i]) + "\n\n"
    i = i + 1
  }

  return result
}

