# ================================================================
# Free IR 1.0 — Node 구조 정의
# Free IR의 모든 노드를 FreeLang으로 표현
# ================================================================

# ----------------------------------------------------------------
# 1. 타입 표현
# ----------------------------------------------------------------

fn ir_type_i8()   { return { "kind": "primitive", "name": "i8",   "size": 1 } }
fn ir_type_i16()  { return { "kind": "primitive", "name": "i16",  "size": 2 } }
fn ir_type_i32()  { return { "kind": "primitive", "name": "i32",  "size": 4 } }
fn ir_type_i64()  { return { "kind": "primitive", "name": "i64",  "size": 8 } }
fn ir_type_u8()   { return { "kind": "primitive", "name": "u8",   "size": 1 } }
fn ir_type_u16()  { return { "kind": "primitive", "name": "u16",  "size": 2 } }
fn ir_type_u32()  { return { "kind": "primitive", "name": "u32",  "size": 4 } }
fn ir_type_u64()  { return { "kind": "primitive", "name": "u64",  "size": 8 } }
fn ir_type_f32()  { return { "kind": "primitive", "name": "f32",  "size": 4 } }
fn ir_type_f64()  { return { "kind": "primitive", "name": "f64",  "size": 8 } }
fn ir_type_bool() { return { "kind": "primitive", "name": "bool", "size": 1 } }
fn ir_type_void() { return { "kind": "primitive", "name": "void", "size": 0 } }

fn ir_type_ptr(inner_type) {
  return { "kind": "ptr", "inner": inner_type, "size": 8 }
}

fn ir_type_array(elem_type, count) {
  size = elem_type["size"] * count
  return { "kind": "array", "elem": elem_type, "count": count, "size": size }
}

fn ir_type_slice(elem_type) {
  return { "kind": "slice", "elem": elem_type, "size": 16 }
}

fn ir_type_struct(name, fields) {
  # fields = [{ "name": str, "type": IrType }, ...]
  # size 계산 (alignment 포함, Phase 1: 단순 합산)
  size = 0
  i = 0
  while i < len(fields) {
    f = fields[i]
    size = size + f["type"]["size"]
    i = i + 1
  }
  return { "kind": "struct", "name": name, "fields": fields, "size": size }
}

fn ir_type_fn(param_types, ret_type) {
  return { "kind": "fn", "params": param_types, "ret": ret_type, "size": 8 }
}

# ----------------------------------------------------------------
# 2. 값(Value) 표현
# ----------------------------------------------------------------

# SSA 값: %name
fn ir_val_reg(name, ty) {
  return { "kind": "reg", "name": name, "type": ty }
}

# 정수 상수
fn ir_val_int(value, ty) {
  return { "kind": "const_int", "value": value, "type": ty }
}

# 부동소수 상수
fn ir_val_float(value, ty) {
  return { "kind": "const_float", "value": value, "type": ty }
}

# bool 상수
fn ir_val_bool(value) {
  return { "kind": "const_bool", "value": value, "type": ir_type_bool() }
}

# null 포인터
fn ir_val_null(ty) {
  return { "kind": "const_null", "type": ty }
}

# 전역 심볼 참조 @name
fn ir_val_global(name, ty) {
  return { "kind": "global_ref", "name": name, "type": ty }
}

# ----------------------------------------------------------------
# 3. Instruction 표현
# ----------------------------------------------------------------

# --- 산술/논리 ---

fn ir_inst_binop(op, result_name, ty, lhs, rhs) {
  # op: "add","sub","mul","div","rem","and","or","xor","shl","shr"
  #     "fadd","fsub","fmul","fdiv"
  return {
    "kind": "binop",
    "op": op,
    "result": result_name,
    "type": ty,
    "lhs": lhs,
    "rhs": rhs
  }
}

fn ir_inst_neg(result_name, ty, operand) {
  return { "kind": "neg", "result": result_name, "type": ty, "operand": operand }
}

# --- 비교 ---

fn ir_inst_icmp(pred, result_name, ty, lhs, rhs) {
  # pred: "eq","ne","lt","le","gt","ge","ult","ule","ugt","uge"
  return {
    "kind": "icmp",
    "pred": pred,
    "result": result_name,
    "type": ty,
    "lhs": lhs,
    "rhs": rhs
  }
}

fn ir_inst_fcmp(pred, result_name, ty, lhs, rhs) {
  # pred: "oeq","one","olt","ole","ogt","oge"
  return {
    "kind": "fcmp",
    "pred": pred,
    "result": result_name,
    "type": ty,
    "lhs": lhs,
    "rhs": rhs
  }
}

# --- 메모리 ---

fn ir_inst_alloca(result_name, ty) {
  # entry block 전용
  ptr_ty = ir_type_ptr(ty)
  return { "kind": "alloca", "result": result_name, "alloc_type": ty, "type": ptr_ty }
}

fn ir_inst_load(result_name, ty, ptr_val) {
  return { "kind": "load", "result": result_name, "type": ty, "ptr": ptr_val }
}

fn ir_inst_store(ty, val, ptr_val) {
  return { "kind": "store", "type": ty, "val": val, "ptr": ptr_val }
}

fn ir_inst_gep(result_name, elem_ty, ptr_val, idx_val) {
  ptr_ty = ir_type_ptr(elem_ty)
  return {
    "kind": "gep",
    "result": result_name,
    "elem_type": elem_ty,
    "ptr": ptr_val,
    "idx": idx_val,
    "type": ptr_ty
  }
}

# --- 타입 변환 ---

fn ir_inst_cast(op, result_name, from_ty, val, to_ty) {
  # op: "trunc","zext","sext","fpext","fptrunc","fptosi","sitofp","bitcast","ptrtoint","inttoptr"
  return {
    "kind": "cast",
    "op": op,
    "result": result_name,
    "from_type": from_ty,
    "val": val,
    "to_type": to_ty,
    "type": to_ty
  }
}

# --- 함수 호출 ---

fn ir_inst_call(result_name, ret_ty, callee, args) {
  # result_name = "" 이면 void 호출
  return {
    "kind": "call",
    "result": result_name,
    "ret_type": ret_ty,
    "callee": callee,
    "args": args,
    "type": ret_ty
  }
}

# --- 제어 흐름 (Terminator) ---

fn ir_inst_br(target_label) {
  return { "kind": "br", "target": target_label }
}

fn ir_inst_br_cond(cond_val, true_label, false_label) {
  return {
    "kind": "br_cond",
    "cond": cond_val,
    "true_label": true_label,
    "false_label": false_label
  }
}

fn ir_inst_ret(val) {
  return { "kind": "ret", "val": val }
}

fn ir_inst_ret_void() {
  return { "kind": "ret_void" }
}

# --- Phi ---

fn ir_inst_phi(result_name, ty, incoming) {
  # incoming = [{ "val": IrVal, "block": string }, ...]
  return {
    "kind": "phi",
    "result": result_name,
    "type": ty,
    "incoming": incoming
  }
}

# ----------------------------------------------------------------
# 4. Basic Block
# ----------------------------------------------------------------

fn ir_block(label, instructions) {
  # instructions = [IrInst, ...]
  # 마지막 inst는 terminator여야 함
  return { "kind": "block", "label": label, "instructions": instructions }
}

fn ir_block_add_inst(block, inst) {
  new_insts = append(block["instructions"], inst)
  return { "kind": "block", "label": block["label"], "instructions": new_insts }
}

fn ir_block_is_terminated(block) {
  insts = block["instructions"]
  n = len(insts)
  if n == 0 { return false }
  last = insts[n - 1]
  k = last["kind"]
  return k == "br" or k == "br_cond" or k == "ret" or k == "ret_void"
}

# ----------------------------------------------------------------
# 5. 함수 정의
# ----------------------------------------------------------------

fn ir_func(name, params, ret_ty, blocks, is_export) {
  # params = [{ "name": string, "type": IrType }, ...]
  # blocks = [IrBlock, ...]
  return {
    "kind": "function",
    "name": name,
    "params": params,
    "ret_type": ret_ty,
    "blocks": blocks,
    "is_export": is_export
  }
}

fn ir_func_extern(name, param_types, ret_ty, is_variadic) {
  return {
    "kind": "extern_fn",
    "name": name,
    "param_types": param_types,
    "ret_type": ret_ty,
    "is_variadic": is_variadic
  }
}

# ----------------------------------------------------------------
# 6. 전역 변수
# ----------------------------------------------------------------

fn ir_global(name, ty, init_val) {
  return { "kind": "global", "name": name, "type": ty, "init": init_val }
}

# ----------------------------------------------------------------
# 7. 모듈
# ----------------------------------------------------------------

fn ir_module(name) {
  return {
    "kind": "module",
    "name": name,
    "globals": [],
    "externs": [],
    "functions": []
  }
}

fn ir_module_add_global(mod, global_def) {
  new_globals = append(mod["globals"], global_def)
  return {
    "kind": "module",
    "name": mod["name"],
    "globals": new_globals,
    "externs": mod["externs"],
    "functions": mod["functions"]
  }
}

fn ir_module_add_extern(mod, extern_def) {
  new_externs = append(mod["externs"], extern_def)
  return {
    "kind": "module",
    "name": mod["name"],
    "globals": mod["globals"],
    "externs": new_externs,
    "functions": mod["functions"]
  }
}

fn ir_module_add_function(mod, func_def) {
  new_fns = append(mod["functions"], func_def)
  return {
    "kind": "module",
    "name": mod["name"],
    "globals": mod["globals"],
    "externs": mod["externs"],
    "functions": new_fns
  }
}

# ----------------------------------------------------------------
# 8. IR 텍스트 출력 (디버깅용)
# ----------------------------------------------------------------

fn ir_type_to_str(ty) {
  k = ty["kind"]
  if k == "primitive" { return ty["name"] }
  if k == "ptr"       { return "ptr<" + ir_type_to_str(ty["inner"]) + ">" }
  if k == "array"     { return "array<" + ir_type_to_str(ty["elem"]) + "," + str(ty["count"]) + ">" }
  if k == "slice"     { return "slice<" + ir_type_to_str(ty["elem"]) + ">" }
  if k == "struct"    { return "struct." + ty["name"] }
  if k == "fn"        { return "fn_ptr" }
  return "unknown_type"
}

fn ir_val_to_str(val) {
  k = val["kind"]
  if k == "reg"         { return "%" + val["name"] }
  if k == "const_int"   { return str(val["value"]) }
  if k == "const_float" { return str(val["value"]) }
  if k == "const_bool"  {
    if val["value"] { return "true" }
    return "false"
  }
  if k == "const_null"  { return "null" }
  if k == "global_ref"  { return "@" + val["name"] }
  return "?"
}

fn ir_inst_to_str(inst) {
  k = inst["kind"]

  if k == "binop" {
    return "%" + inst["result"] + " = " + inst["op"] + " " +
           ir_type_to_str(inst["type"]) + " " +
           ir_val_to_str(inst["lhs"]) + ", " + ir_val_to_str(inst["rhs"])
  }

  if k == "icmp" or k == "fcmp" {
    return "%" + inst["result"] + " = " + k + " " + inst["pred"] + " " +
           ir_type_to_str(inst["type"]) + " " +
           ir_val_to_str(inst["lhs"]) + ", " + ir_val_to_str(inst["rhs"])
  }

  if k == "alloca" {
    return "%" + inst["result"] + " = alloca " + ir_type_to_str(inst["alloc_type"])
  }

  if k == "load" {
    return "%" + inst["result"] + " = load " +
           ir_type_to_str(inst["type"]) + " " + ir_val_to_str(inst["ptr"])
  }

  if k == "store" {
    return "store " + ir_type_to_str(inst["type"]) + " " +
           ir_val_to_str(inst["val"]) + ", " + ir_val_to_str(inst["ptr"])
  }

  if k == "gep" {
    return "%" + inst["result"] + " = gep " +
           ir_type_to_str(inst["elem_type"]) + " " +
           ir_val_to_str(inst["ptr"]) + ", " + ir_val_to_str(inst["idx"])
  }

  if k == "cast" {
    return "%" + inst["result"] + " = " + inst["op"] + " " +
           ir_type_to_str(inst["from_type"]) + " " +
           ir_val_to_str(inst["val"]) + " to " + ir_type_to_str(inst["to_type"])
  }

  if k == "call" {
    args_str = ""
    i = 0
    args = inst["args"]
    while i < len(args) {
      if i > 0 { args_str = args_str + ", " }
      args_str = args_str + ir_val_to_str(args[i])
      i = i + 1
    }
    if inst["result"] == "" {
      return "call void " + ir_val_to_str(inst["callee"]) + "(" + args_str + ")"
    }
    return "%" + inst["result"] + " = call " +
           ir_type_to_str(inst["ret_type"]) + " " +
           ir_val_to_str(inst["callee"]) + "(" + args_str + ")"
  }

  if k == "br"       { return "br label %" + inst["target"] }
  if k == "br_cond"  {
    return "br bool " + ir_val_to_str(inst["cond"]) +
           ", label %" + inst["true_label"] +
           ", label %" + inst["false_label"]
  }
  if k == "ret"      { return "ret " + ir_val_to_str(inst["val"]) }
  if k == "ret_void" { return "ret void" }

  if k == "phi" {
    incoming_str = ""
    i = 0
    ins = inst["incoming"]
    while i < len(ins) {
      if i > 0 { incoming_str = incoming_str + ", " }
      incoming_str = incoming_str + "[" +
        ir_val_to_str(ins[i]["val"]) + ", %" + ins[i]["block"] + "]"
      i = i + 1
    }
    return "%" + inst["result"] + " = phi " +
           ir_type_to_str(inst["type"]) + " " + incoming_str
  }

  return "# unknown_inst: " + k
}

fn ir_block_to_str(block) {
  result = block["label"] + ":\n"
  insts = block["instructions"]
  i = 0
  while i < len(insts) {
    result = result + "  " + ir_inst_to_str(insts[i]) + "\n"
    i = i + 1
  }
  return result
}

fn ir_func_to_str(func) {
  k = func["kind"]

  if k == "extern_fn" {
    params_str = ""
    i = 0
    pts = func["param_types"]
    while i < len(pts) {
      if i > 0 { params_str = params_str + ", " }
      params_str = params_str + ir_type_to_str(pts[i])
      i = i + 1
    }
    if func["is_variadic"] { params_str = params_str + ", ..." }
    return "extern fn @" + func["name"] + "(" + params_str + ") -> " +
           ir_type_to_str(func["ret_type"])
  }

  prefix = "define fn "
  if func["is_export"] { prefix = "export fn " }

  params_str = ""
  i = 0
  params = func["params"]
  while i < len(params) {
    if i > 0 { params_str = params_str + ", " }
    params_str = params_str + ir_type_to_str(params[i]["type"]) + " %" + params[i]["name"]
    i = i + 1
  }

  header = prefix + "@" + func["name"] + "(" + params_str + ") -> " +
           ir_type_to_str(func["ret_type"]) + " {\n"

  body = ""
  i = 0
  blocks = func["blocks"]
  while i < len(blocks) {
    body = body + ir_block_to_str(blocks[i])
    i = i + 1
  }

  return header + body + "}"
}

fn ir_module_to_str(mod) {
  result = "module @" + mod["name"] + "\n\n"

  # extern 선언
  i = 0
  exts = mod["externs"]
  while i < len(exts) {
    result = result + ir_func_to_str(exts[i]) + "\n"
    i = i + 1
  }

  if len(exts) > 0 { result = result + "\n" }

  # 전역 변수
  i = 0
  globs = mod["globals"]
  while i < len(globs) {
    g = globs[i]
    result = result + "global @" + g["name"] + ": " +
             ir_type_to_str(g["type"]) + "\n"
    i = i + 1
  }

  if len(globs) > 0 { result = result + "\n" }

  # 함수
  i = 0
  fns = mod["functions"]
  while i < len(fns) {
    result = result + ir_func_to_str(fns[i]) + "\n\n"
    i = i + 1
  }

  return result
}

input.content:
# ================================================================
# Free IR 1.0 — IR Generator
# AST (FreeLang 파서 출력) → Free IR
#
# 입력: parser.fl 출력 AST 노드
# 출력: ir_node.fl 구조
# ================================================================

# ----------------------------------------------------------------
# 빌더 상태 (불변 함수형 스타일 — context 전달)
# ----------------------------------------------------------------

fn irgen_context(module, current_func, current_block, blocks, reg_count, label_count) {
  return {
    "module":        module,
    "current_func":  current_func,   # 현재 작성 중인 함수 이름
    "current_block": current_block,  # 현재 basic block
    "blocks":        blocks,         # 완성된 블록 목록
    "reg_count":     reg_count,      # SSA 레지스터 카운터
    "label_count":   label_count,    # 레이블 카운터
    "locals":        {},             # 변수명 → alloca ptr val 매핑
    "func_sigs":     {}              # 함수명 → { params, ret_type } 매핑
  }
}

fn irgen_fresh(module_name) {
  mod = ir_module(module_name)
  return irgen_context(mod, "", ir_block("__init__", []), [], 0, 0)
}

# 새 SSA 이름 생성
fn irgen_new_reg(ctx) {
  name = "r" + str(ctx["reg_count"])
  new_ctx = {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": ctx["current_block"],
    "blocks":        ctx["blocks"],
    "reg_count":     ctx["reg_count"] + 1,
    "label_count":   ctx["label_count"],
    "locals":        ctx["locals"],
    "func_sigs":     ctx["func_sigs"]
  }
  return { "name": name, "ctx": new_ctx }
}

# 새 레이블 생성
fn irgen_new_label(ctx, prefix) {
  name = prefix + str(ctx["label_count"])
  new_ctx = {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": ctx["current_block"],
    "blocks":        ctx["blocks"],
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"] + 1,
    "locals":        ctx["locals"],
    "func_sigs":     ctx["func_sigs"]
  }
  return { "name": name, "ctx": new_ctx }
}

# 현재 블록에 instruction 추가
fn irgen_emit(ctx, inst) {
  new_block = ir_block_add_inst(ctx["current_block"], inst)
  return {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": new_block,
    "blocks":        ctx["blocks"],
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"],
    "locals":        ctx["locals"],
    "func_sigs":     ctx["func_sigs"]
  }
}

# 현재 블록을 마무리하고 새 블록 시작
fn irgen_seal_and_start(ctx, new_label) {
  sealed_blocks = append(ctx["blocks"], ctx["current_block"])
  new_block = ir_block(new_label, [])
  return {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": new_block,
    "blocks":        sealed_blocks,
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"],
    "locals":        ctx["locals"],
    "func_sigs":     ctx["func_sigs"]
  }
}

# 지역 변수 등록
fn irgen_set_local(ctx, var_name, ptr_val) {
  new_locals = map_set(ctx["locals"], var_name, ptr_val)
  return {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": ctx["current_block"],
    "blocks":        ctx["blocks"],
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"],
    "locals":        new_locals,
    "func_sigs":     ctx["func_sigs"]
  }
}

# ----------------------------------------------------------------
# AST 타입 → IR 타입 변환
# ----------------------------------------------------------------

fn irgen_resolve_type(type_str) {
  if type_str == "i8"   { return ir_type_i8() }
  if type_str == "i16"  { return ir_type_i16() }
  if type_str == "i32"  { return ir_type_i32() }
  if type_str == "i64"  { return ir_type_i64() }
  if type_str == "u8"   { return ir_type_u8() }
  if type_str == "u16"  { return ir_type_u16() }
  if type_str == "u32"  { return ir_type_u32() }
  if type_str == "u64"  { return ir_type_u64() }
  if type_str == "f32"  { return ir_type_f32() }
  if type_str == "f64"  { return ir_type_f64() }
  if type_str == "bool" { return ir_type_bool() }
  if type_str == "void" { return ir_type_void() }
  # 기본 폴백: i64
  return ir_type_i64()
}

# ----------------------------------------------------------------
# 표현식 코드 생성 → { val, ctx }
# ----------------------------------------------------------------

fn irgen_expr(ctx, ast_node) {
  kind = ast_node["type"]

  # 정수 리터럴
  if kind == "literal" {
    lit_type = ast_node["literalType"]
    if lit_type == "int" or lit_type == "number" {
      val = ir_val_int(ast_node["value"], ir_type_i64())
      return { "val": val, "ctx": ctx }
    }
    if lit_type == "float" {
      val = ir_val_float(ast_node["value"], ir_type_f64())
      return { "val": val, "ctx": ctx }
    }
    if lit_type == "bool" {
      val = ir_val_bool(ast_node["value"])
      return { "val": val, "ctx": ctx }
    }
  }

  # 식별자 (변수 읽기)
  if kind == "identifier" {
    var_name = ast_node["name"]
    locals = ctx["locals"]
    ptr_val = map_get(locals, var_name)

    fresh = irgen_new_reg(ctx)
    reg_name = fresh["name"]
    ctx2 = fresh["ctx"]

    # alloca 된 포인터에서 load
    load_inst = ir_inst_load(reg_name, ir_type_i64(), ptr_val)
    ctx3 = irgen_emit(ctx2, load_inst)

    result_val = ir_val_reg(reg_name, ir_type_i64())
    return { "val": result_val, "ctx": ctx3 }
  }

  # 이항 연산
  if kind == "binaryOp" {
    left_r = irgen_expr(ctx, ast_node["left"])
    lval = left_r["val"]
    ctx1 = left_r["ctx"]

    right_r = irgen_expr(ctx1, ast_node["right"])
    rval = right_r["val"]
    ctx2 = right_r["ctx"]

    op = ast_node["operator"]
    ir_op = irgen_map_binop(op)
    is_cmp = irgen_is_cmp_op(op)

    fresh = irgen_new_reg(ctx2)
    reg_name = fresh["name"]
    ctx3 = fresh["ctx"]

    ty = ir_type_i64()
    result_ty = ty
    if is_cmp { result_ty = ir_type_bool() }

    if is_cmp {
      pred = irgen_map_cmp_pred(op)
      inst = ir_inst_icmp(pred, reg_name, ty, lval, rval)
    } else {
      inst = ir_inst_binop(ir_op, reg_name, ty, lval, rval)
    }

    ctx4 = irgen_emit(ctx3, inst)
    result_val = ir_val_reg(reg_name, result_ty)
    return { "val": result_val, "ctx": ctx4 }
  }

  # 함수 호출
  if kind == "call" {
    callee_node = ast_node["callee"]
    callee_name = callee_node["name"]
    callee_val = ir_val_global(callee_name, ir_type_i64())

    ctx_cur = ctx
    arg_vals = []
    i = 0
    ast_args = ast_node["arguments"]
    while i < len(ast_args) {
      arg_r = irgen_expr(ctx_cur, ast_args[i])
      arg_vals = append(arg_vals, arg_r["val"])
      ctx_cur = arg_r["ctx"]
      i = i + 1
    }

    fresh = irgen_new_reg(ctx_cur)
    reg_name = fresh["name"]
    ctx2 = fresh["ctx"]

    ret_ty = ir_type_i64()
    inst = ir_inst_call(reg_name, ret_ty, callee_val, arg_vals)
    ctx3 = irgen_emit(ctx2, inst)

    result_val = ir_val_reg(reg_name, ret_ty)
    return { "val": result_val, "ctx": ctx3 }
  }

  # 단항 연산
  if kind == "unaryOp" {
    op = ast_node["operator"]
    operand_r = irgen_expr(ctx, ast_node["operand"])
    oval = operand_r["val"]
    ctx1 = operand_r["ctx"]

    if op == "-" {
      fresh = irgen_new_reg(ctx1)
      reg_name = fresh["name"]
      ctx2 = fresh["ctx"]
      inst = ir_inst_neg(reg_name, ir_type_i64(), oval)
      ctx3 = irgen_emit(ctx2, inst)
      result_val = ir_val_reg(reg_name, ir_type_i64())
      return { "val": result_val, "ctx": ctx3 }
    }

    if op == "!" {
      fresh = irgen_new_reg(ctx1)
      reg_name = fresh["name"]
      ctx2 = fresh["ctx"]
      zero = ir_val_int(0, ir_type_i64())
      inst = ir_inst_icmp("eq", reg_name, ir_type_i64(), oval, zero)
      ctx3 = irgen_emit(ctx2, inst)
      result_val = ir_val_reg(reg_name, ir_type_bool())
      return { "val": result_val, "ctx": ctx3 }
    }
  }

  # 폴백: 0 반환
  return { "val": ir_val_int(0, ir_type_i64()), "ctx": ctx }
}

# 연산자 매핑
fn irgen_map_binop(op) {
  if op == "+"  { return "add" }
  if op == "-"  { return "sub" }
  if op == "*"  { return "mul" }
  if op == "/"  { return "div" }
  if op == "%"  { return "rem" }
  if op == "&"  { return "and" }
  if op == "|"  { return "or" }
  if op == "^"  { return "xor" }
  if op == "<<" { return "shl" }
  if op == ">>" { return "shr" }
  return "add"
}

fn irgen_is_cmp_op(op) {
  if op == "==" { return true }
  if op == "!=" { return true }
  if op == "<"  { return true }
  if op == "<=" { return true }
  if op == ">"  { return true }
  if op == ">=" { return true }
  return false
}

fn irgen_map_cmp_pred(op) {
  if op == "==" { return "eq" }
  if op == "!=" { return "ne" }
  if op == "<"  { return "lt" }
  if op == "<=" { return "le" }
  if op == ">"  { return "gt" }
  if op == ">=" { return "ge" }
  return "eq"
}

# ----------------------------------------------------------------
# 문장 코드 생성 → ctx
# ----------------------------------------------------------------

fn irgen_stmt(ctx, ast_node) {
  kind = ast_node["type"]

  # 변수 대입 / 선언
  if kind == "assignment" {
    var_name = ast_node["variable"]
    locals = ctx["locals"]
    ptr_val = map_get(locals, var_name)

    # 아직 선언 안 됐으면 alloca 생성
    if ptr_val == null {
      fresh = irgen_new_reg(ctx)
      ptr_name = fresh["name"]
      ctx = fresh["ctx"]

      alloca_inst = ir_inst_alloca(ptr_name, ir_type_i64())
      ctx = irgen_emit(ctx, alloca_inst)

      ptr_val = ir_val_reg(ptr_name, ir_type_ptr(ir_type_i64()))
      ctx = irgen_set_local(ctx, var_name, ptr_val)
    }

    rhs = irgen_expr(ctx, ast_node["value"])
    rval = rhs["val"]
    ctx = rhs["ctx"]

    store_inst = ir_inst_store(ir_type_i64(), rval, ptr_val)
    ctx = irgen_emit(ctx, store_inst)
    return ctx
  }

  # return 문
  if kind == "returnStatement" {
    if ast_node["value"] == null {
      ctx = irgen_emit(ctx, ir_inst_ret_void())
      return ctx
    }
    rhs = irgen_expr(ctx, ast_node["value"])
    ctx = irgen_emit(ctx, ir_inst_ret(rhs["val"]))
    return rhs["ctx"]
  }

  # if 문
  if kind == "ifStatement" {
    # 조건 평가
    cond_r = irgen_expr(ctx, ast_node["condition"])
    cond_val = cond_r["val"]
    ctx = cond_r["ctx"]

    # 레이블 생성
    then_l = irgen_new_label(ctx, "then")
    then_label = then_l["name"]
    ctx = then_l["ctx"]

    has_else = len(ast_node["else"]) > 0

    if has_else {
      else_l = irgen_new_label(ctx, "else")
      else_label = else_l["name"]
      ctx = else_l["ctx"]
    } else {
      else_label = ""
    }

    merge_l = irgen_new_label(ctx, "merge")
    merge_label = merge_l["name"]
    ctx = merge_l["ctx"]

    if has_else {
      ctx = irgen_emit(ctx, ir_inst_br_cond(cond_val, then_label, else_label))
    } else {
      ctx = irgen_emit(ctx, ir_inst_br_cond(cond_val, then_label, merge_label))
    }

    # then 블록
    ctx = irgen_seal_and_start(ctx, then_label)
    i = 0
    then_stmts = ast_node["then"]
    while i < len(then_stmts) {
      ctx = irgen_stmt(ctx, then_stmts[i])
      i = i + 1
    }
    if not ir_block_is_terminated(ctx["current_block"]) {
      ctx = irgen_emit(ctx, ir_inst_br(merge_label))
    }

    # else 블록
    if has_else {
      ctx = irgen_seal_and_start(ctx, else_label)
      i = 0
      else_stmts = ast_node["else"]
      while i < len(else_stmts) {
        ctx = irgen_stmt(ctx, else_stmts[i])
        i = i + 1
      }
      if not ir_block_is_terminated(ctx["current_block"]) {
        ctx = irgen_emit(ctx, ir_inst_br(merge_label))
      }
    }

    # merge 블록 시작
    ctx = irgen_seal_and_start(ctx, merge_label)
    return ctx
  }

  # while 문
  if kind == "whileStatement" {
    cond_l = irgen_new_label(ctx, "loop_cond")
    cond_label = cond_l["name"]
    ctx = cond_l["ctx"]

    body_l = irgen_new_label(ctx, "loop_body")
    body_label = body_l["name"]
    ctx = body_l["ctx"]

    exit_l = irgen_new_label(ctx, "loop_exit")
    exit_label = exit_l["name"]
    ctx = exit_l["ctx"]

    # 현재 블록 → cond 블록
    ctx = irgen_emit(ctx, ir_inst_br(cond_label))
    ctx = irgen_seal_and_start(ctx, cond_label)

    # 조건 평가
    cond_r = irgen_expr(ctx, ast_node["condition"])
    cond_val = cond_r["val"]
    ctx = cond_r["ctx"]
    ctx = irgen_emit(ctx, ir_inst_br_cond(cond_val, body_label, exit_label))

    # body 블록
    ctx = irgen_seal_and_start(ctx, body_label)
    i = 0
    body_stmts = ast_node["body"]
    while i < len(body_stmts) {
      ctx = irgen_stmt(ctx, body_stmts[i])
      i = i + 1
    }
    if not ir_block_is_terminated(ctx["current_block"]) {
      ctx = irgen_emit(ctx, ir_inst_br(cond_label))
    }

    # exit 블록
    ctx = irgen_seal_and_start(ctx, exit_label)
    return ctx
  }

  # 함수 호출 (표현식 문장)
  if kind == "call" {
    expr_r = irgen_expr(ctx, ast_node)
    return expr_r["ctx"]
  }

  # 블록
  if kind == "blockStatement" {
    i = 0
    stmts = ast_node["statements"]
    while i < len(stmts) {
      ctx = irgen_stmt(ctx, stmts[i])
      i = i + 1
    }
    return ctx
  }

  return ctx
}

# ----------------------------------------------------------------
# 함수 정의 코드 생성
# ----------------------------------------------------------------

fn irgen_function(ctx, func_ast) {
  func_name = func_ast["name"]
  params = func_ast["params"]
  body = func_ast["body"]

  # 파라미터 타입 정의 (Phase 1: 전부 i64)
  ir_params = []
  i = 0
  while i < len(params) {
    p = params[i]
    p_name = p
    if type(p) == "object" { p_name = p["name"] }
    ir_params = append(ir_params, { "name": p_name, "type": ir_type_i64() })
    i = i + 1
  }

  # entry 블록 시작
  ctx = irgen_seal_and_start(ctx, "entry")
  ctx = {
    "module":        ctx["module"],
    "current_func":  func_name,
    "current_block": ctx["current_block"],
    "blocks":        [],
    "reg_count":     0,
    "label_count":   0,
    "locals":        {},
    "func_sigs":     ctx["func_sigs"]
  }

  # 파라미터 → alloca + store (메모리 모델)
  i = 0
  while i < len(ir_params) {
    p = ir_params[i]
    p_name = p["name"]

    fresh = irgen_new_reg(ctx)
    ptr_reg = fresh["name"]
    ctx = fresh["ctx"]

    alloca_inst = ir_inst_alloca(ptr_reg, ir_type_i64())
    ctx = irgen_emit(ctx, alloca_inst)

    ptr_val = ir_val_reg(ptr_reg, ir_type_ptr(ir_type_i64()))
    param_val = ir_val_reg(p_name, ir_type_i64())
    store_inst = ir_inst_store(ir_type_i64(), param_val, ptr_val)
    ctx = irgen_emit(ctx, store_inst)

    ctx = irgen_set_local(ctx, p_name, ptr_val)
    i = i + 1
  }

  # body 코드 생성
  i = 0
  while i < len(body) {
    ctx = irgen_stmt(ctx, body[i])
    i = i + 1
  }

  # 마지막 블록 종료 보장
  if not ir_block_is_terminated(ctx["current_block"]) {
    ctx = irgen_emit(ctx, ir_inst_ret_void())
  }

  # 모든 블록 수집
  all_blocks = append(ctx["blocks"], ctx["current_block"])

  # 함수 노드 생성
  is_export = false
  func_node = ir_func(func_name, ir_params, ir_type_i64(), all_blocks, is_export)

  # 모듈에 추가
  new_mod = ir_module_add_function(ctx["module"], func_node)
  ctx = {
    "module":        new_mod,
    "current_func":  "",
    "current_block": ir_block("__init__", []),
    "blocks":        [],
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"],
    "locals":        {},
    "func_sigs":     ctx["func_sigs"]
  }

  return ctx
}

# ----------------------------------------------------------------
# 모듈 전체 코드 생성 (진입점)
# ----------------------------------------------------------------

fn irgen_module(module_name, ast_program) {
  ctx = irgen_fresh(module_name)

  i = 0
  top_level = ast_program
  while i < len(top_level) {
    node = top_level[i]
    kind = node["type"]

    if kind == "functionDefinition" {
      ctx = irgen_function(ctx, node)
    }

    i = i + 1
  }

  return ctx["module"]
}

# ----------------------------------------------------------------
# 유틸: map_get / map_set (FreeLang 폴리필)
# FreeLang 런타임에 map 지원이 없을 경우를 위한 폴백
# ----------------------------------------------------------------

fn map_get(m, key) {
  if m == null { return null }
  if m[key] != null { return m[key] }
  return null
}

fn map_set(m, key, value) {
  if m == null { m = {} }
  m[key] = value
  return m
}

toolUseResult.content:
# ================================================================
# Free IR 1.0 — IR Generator
# AST (FreeLang 파서 출력) → Free IR
#
# 입력: parser.fl 출력 AST 노드
# 출력: ir_node.fl 구조
# ================================================================

# ----------------------------------------------------------------
# 빌더 상태 (불변 함수형 스타일 — context 전달)
# ----------------------------------------------------------------

fn irgen_context(module, current_func, current_block, blocks, reg_count, label_count) {
  return {
    "module":        module,
    "current_func":  current_func,   # 현재 작성 중인 함수 이름
    "current_block": current_block,  # 현재 basic block
    "blocks":        blocks,         # 완성된 블록 목록
    "reg_count":     reg_count,      # SSA 레지스터 카운터
    "label_count":   label_count,    # 레이블 카운터
    "locals":        {},             # 변수명 → alloca ptr val 매핑
    "func_sigs":     {}              # 함수명 → { params, ret_type } 매핑
  }
}

fn irgen_fresh(module_name) {
  mod = ir_module(module_name)
  return irgen_context(mod, "", ir_block("__init__", []), [], 0, 0)
}

# 새 SSA 이름 생성
fn irgen_new_reg(ctx) {
  name = "r" + str(ctx["reg_count"])
  new_ctx = {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": ctx["current_block"],
    "blocks":        ctx["blocks"],
    "reg_count":     ctx["reg_count"] + 1,
    "label_count":   ctx["label_count"],
    "locals":        ctx["locals"],
    "func_sigs":     ctx["func_sigs"]
  }
  return { "name": name, "ctx": new_ctx }
}

# 새 레이블 생성
fn irgen_new_label(ctx, prefix) {
  name = prefix + str(ctx["label_count"])
  new_ctx = {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": ctx["current_block"],
    "blocks":        ctx["blocks"],
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"] + 1,
    "locals":        ctx["locals"],
    "func_sigs":     ctx["func_sigs"]
  }
  return { "name": name, "ctx": new_ctx }
}

# 현재 블록에 instruction 추가
fn irgen_emit(ctx, inst) {
  new_block = ir_block_add_inst(ctx["current_block"], inst)
  return {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": new_block,
    "blocks":        ctx["blocks"],
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"],
    "locals":        ctx["locals"],
    "func_sigs":     ctx["func_sigs"]
  }
}

# 현재 블록을 마무리하고 새 블록 시작
fn irgen_seal_and_start(ctx, new_label) {
  sealed_blocks = append(ctx["blocks"], ctx["current_block"])
  new_block = ir_block(new_label, [])
  return {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": new_block,
    "blocks":        sealed_blocks,
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"],
    "locals":        ctx["locals"],
    "func_sigs":     ctx["func_sigs"]
  }
}

# 지역 변수 등록
fn irgen_set_local(ctx, var_name, ptr_val) {
  new_locals = map_set(ctx["locals"], var_name, ptr_val)
  return {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": ctx["current_block"],
    "blocks":        ctx["blocks"],
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"],
    "locals":        new_locals,
    "func_sigs":     ctx["func_sigs"]
  }
}

# ----------------------------------------------------------------
# AST 타입 → IR 타입 변환
# ----------------------------------------------------------------

fn irgen_resolve_type(type_str) {
  if type_str == "i8"   { return ir_type_i8() }
  if type_str == "i16"  { return ir_type_i16() }
  if type_str == "i32"  { return ir_type_i32() }
  if type_str == "i64"  { return ir_type_i64() }
  if type_str == "u8"   { return ir_type_u8() }
  if type_str == "u16"  { return ir_type_u16() }
  if type_str == "u32"  { return ir_type_u32() }
  if type_str == "u64"  { return ir_type_u64() }
  if type_str == "f32"  { return ir_type_f32() }
  if type_str == "f64"  { return ir_type_f64() }
  if type_str == "bool" { return ir_type_bool() }
  if type_str == "void" { return ir_type_void() }
  # 기본 폴백: i64
  return ir_type_i64()
}

# ----------------------------------------------------------------
# 표현식 코드 생성 → { val, ctx }
# ----------------------------------------------------------------

fn irgen_expr(ctx, ast_node) {
  kind = ast_node["type"]

  # 정수 리터럴
  if kind == "literal" {
    lit_type = ast_node["literalType"]
    if lit_type == "int" or lit_type == "number" {
      val = ir_val_int(ast_node["value"], ir_type_i64())
      return { "val": val, "ctx": ctx }
    }
    if lit_type == "float" {
      val = ir_val_float(ast_node["value"], ir_type_f64())
      return { "val": val, "ctx": ctx }
    }
    if lit_type == "bool" {
      val = ir_val_bool(ast_node["value"])
      return { "val": val, "ctx": ctx }
    }
  }

  # 식별자 (변수 읽기)
  if kind == "identifier" {
    var_name = ast_node["name"]
    locals = ctx["locals"]
    ptr_val = map_get(locals, var_name)

    fresh = irgen_new_reg(ctx)
    reg_name = fresh["name"]
    ctx2 = fresh["ctx"]

    # alloca 된 포인터에서 load
    load_inst = ir_inst_load(reg_name, ir_type_i64(), ptr_val)
    ctx3 = irgen_emit(ctx2, load_inst)

    result_val = ir_val_reg(reg_name, ir_type_i64())
    return { "val": result_val, "ctx": ctx3 }
  }

  # 이항 연산
  if kind == "binaryOp" {
    left_r = irgen_expr(ctx, ast_node["left"])
    lval = left_r["val"]
    ctx1 = left_r["ctx"]

    right_r = irgen_expr(ctx1, ast_node["right"])
    rval = right_r["val"]
    ctx2 = right_r["ctx"]

    op = ast_node["operator"]
    ir_op = irgen_map_binop(op)
    is_cmp = irgen_is_cmp_op(op)

    fresh = irgen_new_reg(ctx2)
    reg_name = fresh["name"]
    ctx3 = fresh["ctx"]

    ty = ir_type_i64()
    result_ty = ty
    if is_cmp { result_ty = ir_type_bool() }

    if is_cmp {
      pred = irgen_map_cmp_pred(op)
      inst = ir_inst_icmp(pred, reg_name, ty, lval, rval)
    } else {
      inst = ir_inst_binop(ir_op, reg_name, ty, lval, rval)
    }

    ctx4 = irgen_emit(ctx3, inst)
    result_val = ir_val_reg(reg_name, result_ty)
    return { "val": result_val, "ctx": ctx4 }
  }

  # 함수 호출
  if kind == "call" {
    callee_node = ast_node["callee"]
    callee_name = callee_node["name"]
    callee_val = ir_val_global(callee_name, ir_type_i64())

    ctx_cur = ctx
    arg_vals = []
    i = 0
    ast_args = ast_node["arguments"]
    while i < len(ast_args) {
      arg_r = irgen_expr(ctx_cur, ast_args[i])
      arg_vals = append(arg_vals, arg_r["val"])
      ctx_cur = arg_r["ctx"]
      i = i + 1
    }

    fresh = irgen_new_reg(ctx_cur)
    reg_name = fresh["name"]
    ctx2 = fresh["ctx"]

    ret_ty = ir_type_i64()
    inst = ir_inst_call(reg_name, ret_ty, callee_val, arg_vals)
    ctx3 = irgen_emit(ctx2, inst)

    result_val = ir_val_reg(reg_name, ret_ty)
    return { "val": result_val, "ctx": ctx3 }
  }

  # 단항 연산
  if kind == "unaryOp" {
    op = ast_node["operator"]
    operand_r = irgen_expr(ctx, ast_node["operand"])
    oval = operand_r["val"]
    ctx1 = operand_r["ctx"]

    if op == "-" {
      fresh = irgen_new_reg(ctx1)
      reg_name = fresh["name"]
      ctx2 = fresh["ctx"]
      inst = ir_inst_neg(reg_name, ir_type_i64(), oval)
      ctx3 = irgen_emit(ctx2, inst)
      result_val = ir_val_reg(reg_name, ir_type_i64())
      return { "val": result_val, "ctx": ctx3 }
    }

    if op == "!" {
      fresh = irgen_new_reg(ctx1)
      reg_name = fresh["name"]
      ctx2 = fresh["ctx"]
      zero = ir_val_int(0, ir_type_i64())
      inst = ir_inst_icmp("eq", reg_name, ir_type_i64(), oval, zero)
      ctx3 = irgen_emit(ctx2, inst)
      result_val = ir_val_reg(reg_name, ir_type_bool())
      return { "val": result_val, "ctx": ctx3 }
    }
  }

  # 폴백: 0 반환
  return { "val": ir_val_int(0, ir_type_i64()), "ctx": ctx }
}

# 연산자 매핑
fn irgen_map_binop(op) {
  if op == "+"  { return "add" }
  if op == "-"  { return "sub" }
  if op == "*"  { return "mul" }
  if op == "/"  { return "div" }
  if op == "%"  { return "rem" }
  if op == "&"  { return "and" }
  if op == "|"  { return "or" }
  if op == "^"  { return "xor" }
  if op == "<<" { return "shl" }
  if op == ">>" { return "shr" }
  return "add"
}

fn irgen_is_cmp_op(op) {
  if op == "==" { return true }
  if op == "!=" { return true }
  if op == "<"  { return true }
  if op == "<=" { return true }
  if op == ">"  { return true }
  if op == ">=" { return true }
  return false
}

fn irgen_map_cmp_pred(op) {
  if op == "==" { return "eq" }
  if op == "!=" { return "ne" }
  if op == "<"  { return "lt" }
  if op == "<=" { return "le" }
  if op == ">"  { return "gt" }
  if op == ">=" { return "ge" }
  return "eq"
}

# ----------------------------------------------------------------
# 문장 코드 생성 → ctx
# ----------------------------------------------------------------

fn irgen_stmt(ctx, ast_node) {
  kind = ast_node["type"]

  # 변수 대입 / 선언
  if kind == "assignment" {
    var_name = ast_node["variable"]
    locals = ctx["locals"]
    ptr_val = map_get(locals, var_name)

    # 아직 선언 안 됐으면 alloca 생성
    if ptr_val == null {
      fresh = irgen_new_reg(ctx)
      ptr_name = fresh["name"]
      ctx = fresh["ctx"]

      alloca_inst = ir_inst_alloca(ptr_name, ir_type_i64())
      ctx = irgen_emit(ctx, alloca_inst)

      ptr_val = ir_val_reg(ptr_name, ir_type_ptr(ir_type_i64()))
      ctx = irgen_set_local(ctx, var_name, ptr_val)
    }

    rhs = irgen_expr(ctx, ast_node["value"])
    rval = rhs["val"]
    ctx = rhs["ctx"]

    store_inst = ir_inst_store(ir_type_i64(), rval, ptr_val)
    ctx = irgen_emit(ctx, store_inst)
    return ctx
  }

  # return 문
  if kind == "returnStatement" {
    if ast_node["value"] == null {
      ctx = irgen_emit(ctx, ir_inst_ret_void())
      return ctx
    }
    rhs = irgen_expr(ctx, ast_node["value"])
    ctx = irgen_emit(ctx, ir_inst_ret(rhs["val"]))
    return rhs["ctx"]
  }

  # if 문
  if kind == "ifStatement" {
    # 조건 평가
    cond_r = irgen_expr(ctx, ast_node["condition"])
    cond_val = cond_r["val"]
    ctx = cond_r["ctx"]

    # 레이블 생성
    then_l = irgen_new_label(ctx, "then")
    then_label = then_l["name"]
    ctx = then_l["ctx"]

    has_else = len(ast_node["else"]) > 0

    if has_else {
      else_l = irgen_new_label(ctx, "else")
      else_label = else_l["name"]
      ctx = else_l["ctx"]
    } else {
      else_label = ""
    }

    merge_l = irgen_new_label(ctx, "merge")
    merge_label = merge_l["name"]
    ctx = merge_l["ctx"]

    if has_else {
      ctx = irgen_emit(ctx, ir_inst_br_cond(cond_val, then_label, else_label))
    } else {
      ctx = irgen_emit(ctx, ir_inst_br_cond(cond_val, then_label, merge_label))
    }

    # then 블록
    ctx = irgen_seal_and_start(ctx, then_label)
    i = 0
    then_stmts = ast_node["then"]
    while i < len(then_stmts) {
      ctx = irgen_stmt(ctx, then_stmts[i])
      i = i + 1
    }
    if not ir_block_is_terminated(ctx["current_block"]) {
      ctx = irgen_emit(ctx, ir_inst_br(merge_label))
    }

    # else 블록
    if has_else {
      ctx = irgen_seal_and_start(ctx, else_label)
      i = 0
      else_stmts = ast_node["else"]
      while i < len(else_stmts) {
        ctx = irgen_stmt(ctx, else_stmts[i])
        i = i + 1
      }
      if not ir_block_is_terminated(ctx["current_block"]) {
        ctx = irgen_emit(ctx, ir_inst_br(merge_label))
      }
    }

    # merge 블록 시작
    ctx = irgen_seal_and_start(ctx, merge_label)
    return ctx
  }

  # while 문
  if kind == "whileStatement" {
    cond_l = irgen_new_label(ctx, "loop_cond")
    cond_label = cond_l["name"]
    ctx = cond_l["ctx"]

    body_l = irgen_new_label(ctx, "loop_body")
    body_label = body_l["name"]
    ctx = body_l["ctx"]

    exit_l = irgen_new_label(ctx, "loop_exit")
    exit_label = exit_l["name"]
    ctx = exit_l["ctx"]

    # 현재 블록 → cond 블록
    ctx = irgen_emit(ctx, ir_inst_br(cond_label))
    ctx = irgen_seal_and_start(ctx, cond_label)

    # 조건 평가
    cond_r = irgen_expr(ctx, ast_node["condition"])
    cond_val = cond_r["val"]
    ctx = cond_r["ctx"]
    ctx = irgen_emit(ctx, ir_inst_br_cond(cond_val, body_label, exit_label))

    # body 블록
    ctx = irgen_seal_and_start(ctx, body_label)
    i = 0
    body_stmts = ast_node["body"]
    while i < len(body_stmts) {
      ctx = irgen_stmt(ctx, body_stmts[i])
      i = i + 1
    }
    if not ir_block_is_terminated(ctx["current_block"]) {
      ctx = irgen_emit(ctx, ir_inst_br(cond_label))
    }

    # exit 블록
    ctx = irgen_seal_and_start(ctx, exit_label)
    return ctx
  }

  # 함수 호출 (표현식 문장)
  if kind == "call" {
    expr_r = irgen_expr(ctx, ast_node)
    return expr_r["ctx"]
  }

  # 블록
  if kind == "blockStatement" {
    i = 0
    stmts = ast_node["statements"]
    while i < len(stmts) {
      ctx = irgen_stmt(ctx, stmts[i])
      i = i + 1
    }
    return ctx
  }

  return ctx
}

# ----------------------------------------------------------------
# 함수 정의 코드 생성
# ----------------------------------------------------------------

fn irgen_function(ctx, func_ast) {
  func_name = func_ast["name"]
  params = func_ast["params"]
  body = func_ast["body"]

  # 파라미터 타입 정의 (Phase 1: 전부 i64)
  ir_params = []
  i = 0
  while i < len(params) {
    p = params[i]
    p_name = p
    if type(p) == "object" { p_name = p["name"] }
    ir_params = append(ir_params, { "name": p_name, "type": ir_type_i64() })
    i = i + 1
  }

  # entry 블록 시작
  ctx = irgen_seal_and_start(ctx, "entry")
  ctx = {
    "module":        ctx["module"],
    "current_func":  func_name,
    "current_block": ctx["current_block"],
    "blocks":        [],
    "reg_count":     0,
    "label_count":   0,
    "locals":        {},
    "func_sigs":     ctx["func_sigs"]
  }

  # 파라미터 → alloca + store (메모리 모델)
  i = 0
  while i < len(ir_params) {
    p = ir_params[i]
    p_name = p["name"]

    fresh = irgen_new_reg(ctx)
    ptr_reg = fresh["name"]
    ctx = fresh["ctx"]

    alloca_inst = ir_inst_alloca(ptr_reg, ir_type_i64())
    ctx = irgen_emit(ctx, alloca_inst)

    ptr_val = ir_val_reg(ptr_reg, ir_type_ptr(ir_type_i64()))
    param_val = ir_val_reg(p_name, ir_type_i64())
    store_inst = ir_inst_store(ir_type_i64(), param_val, ptr_val)
    ctx = irgen_emit(ctx, store_inst)

    ctx = irgen_set_local(ctx, p_name, ptr_val)
    i = i + 1
  }

  # body 코드 생성
  i = 0
  while i < len(body) {
    ctx = irgen_stmt(ctx, body[i])
    i = i + 1
  }

  # 마지막 블록 종료 보장
  if not ir_block_is_terminated(ctx["current_block"]) {
    ctx = irgen_emit(ctx, ir_inst_ret_void())
  }

  # 모든 블록 수집
  all_blocks = append(ctx["blocks"], ctx["current_block"])

  # 함수 노드 생성
  is_export = false
  func_node = ir_func(func_name, ir_params, ir_type_i64(), all_blocks, is_export)

  # 모듈에 추가
  new_mod = ir_module_add_function(ctx["module"], func_node)
  ctx = {
    "module":        new_mod,
    "current_func":  "",
    "current_block": ir_block("__init__", []),
    "blocks":        [],
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"],
    "locals":        {},
    "func_sigs":     ctx["func_sigs"]
  }

  return ctx
}

# ----------------------------------------------------------------
# 모듈 전체 코드 생성 (진입점)
# ----------------------------------------------------------------

fn irgen_module(module_name, ast_program) {
  ctx = irgen_fresh(module_name)

  i = 0
  top_level = ast_program
  while i < len(top_level) {
    node = top_level[i]
    kind = node["type"]

    if kind == "functionDefinition" {
      ctx = irgen_function(ctx, node)
    }

    i = i + 1
  }

  return ctx["module"]
}

# ----------------------------------------------------------------
# 유틸: map_get / map_set (FreeLang 폴리필)
# FreeLang 런타임에 map 지원이 없을 경우를 위한 폴백
# ----------------------------------------------------------------

fn map_get(m, key) {
  if m == null { return null }
  if m[key] != null { return m[key] }
  return null
}

fn map_set(m, key, value) {
  if m == null { m = {} }
  m[key] = value
  return m
}

