fn test_irgen_add() {
  println("=== Test 3: IRGen - add function ===")

  # 다음 FreeLang AST를 IR로 변환:
  #   fn add(a, b) {
  #     return a + b
  #   }

  add_ast = {
    "type": "functionDefinition",
    "name": "add",
    "params": ["a", "b"],
    "body": [
      {
        "type": "returnStatement",
        "value": {
          "type": "binaryOp",
          "operator": "+",
