  # entry 블록에 load + add + ret 있는지
  blocks = fns[0]["blocks"]
  assert(len(blocks) > 0,           "has at least one block")

  println("[PASS] Test 3: IRGen add")
  return true
}

# ----------------------------------------------------------------
# Test 4: IR 생성기 — if 조건문
# ----------------------------------------------------------------

fn test_irgen_if() {
  println("=== Test 4: IRGen - if statement ===")

  # fn abs(x) {
  #   if x < 0 {
  #     return 0 - x
  #   }
  #   return x
  # }

  abs_ast = {
    "type": "functionDefinition",
    "name": "abs",
    "params": ["x"],
    "body": [
      {
        "type": "ifStatement",
        "condition": {
          "type": "binaryOp",
          "operator": "<",
          "left":  { "type": "identifier", "name": "x" },
          "right": { "type": "literal", "literalType": "int", "value": 0 }
        },
        "then": [
          {
            "type": "returnStatement",
            "value": {
              "type": "binaryOp",
              "operator": "-",
              "left":  { "type": "literal", "literalType": "int", "value": 0 },
              "right": { "type": "identifier", "name": "x" }
            }
          }
        ],
        "else": []
      },
      {
        "type": "returnStatement",
        "value": { "type": "identifier", "name": "x" }
      }
    ]
  }

  ir_mod = irgen_module("test_abs", [abs_ast])
  ir_text = ir_module_to_str(ir_mod)
  println(ir_text)

  fns = ir_mod["functions"]
  assert(len(fns) == 1, "one function")
  # if → then/merge 블록 최소 3개 이상
  blocks = fns[0]["blocks"]
  assert(len(blocks) >= 3, "if generates multiple blocks")

  println("[PASS] Test 4: IRGen if")
  return true
}

# ----------------------------------------------------------------
# Test 5: IR 생성기 — while 루프
# ----------------------------------------------------------------

fn test_irgen_while() {
  println("=== Test 5: IRGen - while loop ===")

  # fn sum_to(n) {
  #   i = 0
  #   s = 0
  #   while i < n {
  #     s = s + i
  #     i = i + 1
  #   }
  #   return s
  # }

  sum_ast = {
    "type": "functionDefinition",
    "name": "sum_to",
    "params": ["n"],
    "body": [
      { "type": "assignment", "variable": "i",
        "value": { "type": "literal", "literalType": "int", "value": 0 } },
      { "type": "assignment", "variable": "s",
        "value": { "type": "literal", "literalType": "int", "value": 0 } },
      {
        "type": "whileStatement",
        "condition": {
          "type": "binaryOp", "operator": "<",
          "left":  { "type": "identifier", "name": "i" },
          "right": { "type": "identifier", "name": "n" }
        },
        "body": [
          { "type": "assignment", "variable": "s",
            "value": {
              "type": "binaryOp", "operator": "+",
              "left":  { "type": "identifier", "name": "s" },
              "right": { "type": "identifier", "name": "i" }
            }
          },
          { "type": "assignment", "variable": "i",
            "value": {
              "type": "binaryOp", "operator": "+",
              "left":  { "type": "identifier", "name": "i" },
              "right": { "type": "literal", "literalType": "int", "value": 1 }
            }
          }
        ]
      },
      { "type": "returnStatement",
        "value": { "type": "identifier", "name": "s" } }
    ]
  }

  ir_mod = irgen_module("test_while", [sum_ast])
  ir_text = ir_module_to_str(ir_mod)
  println(ir_text)

  fns = ir_mod["functions"]
  assert(len(fns) == 1, "one function")
  blocks = fns[0]["blocks"]
  # while → loop_cond + loop_body + loop_exit + entry = 최소 4개
  assert(len(blocks) >= 4, "while generates 4+ blocks")

  println("[PASS] Test 5: IRGen while")
  return true
}

# ----------------------------------------------------------------
# assert 유틸
# ----------------------------------------------------------------

fn assert(cond, msg) {
  if not cond {
    println("FAIL: " + msg)
    return false
  }
  return true
}

# ----------------------------------------------------------------
# 메인
# ----------------------------------------------------------------

fn main() {
  println("Free IR 1.0 — Node & Generator Tests")
  println("========================================")

  r1 = test_types()
  r2 = test_manual_ir()
  r3 = test_irgen_add()
