  slice_t = ir_type_slice(ir_type_i32())
  assert(slice_t["kind"] == "slice","slice kind")
  assert(slice_t["size"] == 16,     "slice size (ptr+len)")

  println("[PASS] Test 2: Type System")
  return true
}

# ----------------------------------------------------------------
# Test 3: IR 생성기 — 간단한 덧셈 함수
# ----------------------------------------------------------------

fn test_irgen_add() {
  println("=== Test 3: IRGen - add function ===")

  # 다음 FreeLang AST를 IR로 변환:
  #   fn add(a, b) {
  #     return a + b
  #   }

  add_ast = {
    "type": "functionDefinition",
    "name": "add",
    "params": ["a", "b"],
    "body": [
      {
        "type": "returnStatement",
        "value": {
          "type": "binaryOp",
          "operator": "+",
          "left":  { "type": "identifier", "name": "a" },
          "right": { "type": "identifier", "name": "b" }
        }
      }
    ]
  }

  program = [add_ast]
  ir_mod = irgen_module("test_add", program)
  ir_text = ir_module_to_str(ir_mod)

  println(ir_text)

  # 검증: "add" 함수가 생성됐는지
  fns = ir_mod["functions"]
  assert(len(fns) == 1,             "one function generated")
  assert(fns[0]["name"] == "add",   "function name is add")

  # entry 블록에 load + add + ret 있는지
  blocks = fns[0]["blocks"]
  assert(len(blocks) > 0,           "has at least one block")

  println("[PASS] Test 3: IRGen add")
  return true
}

# ----------------------------------------------------------------
# Test 4: IR 생성기 — if 조건문
# ----------------------------------------------------------------

fn test_irgen_if() {
  println("=== Test 4: IRGen - if statement ===")

  # fn abs(x) {
  #   if x < 0 {
  #     return 0 - x
  #   }
  #   return x
  # }

  abs_ast = {
    "type": "functionDefinition",
    "name": "abs",
    "params": ["x"],
    "body": [
      {
        "type": "ifStatement",
        "condition": {
          "type": "binaryOp",
          "operator": "<",
          "left":  { "type": "identifier", "name": "x" },
          "right": { "type": "literal", "literalType": "int", "value": 0 }
        },
        "then": [
          {
            "type": "returnStatement",
            "value": {
              "type": "binaryOp",
              "operator": "-",
              "left":  { "type": "literal", "literalType": "int", "value": 0 },
              "right": { "type": "identifier", "name": "x" }
            }
          }
        ],
        "else": []
      },
      {
        "type": "returnStatement",
        "value": { "type": "identifier", "name": "x" }
      }
    ]
  }

  ir_mod = irgen_module("test_abs", [abs_ast])
  ir_text = ir_module_to_str(ir_mod)
  println(ir_text)

  fns = ir_mod["functions"]
  assert(len(fns) == 1, "one function")
  # if → then/merge 블록 최소 3개 이상
  blocks = fns[0]["blocks"]
  assert(len(blocks) >= 3, "if generates multiple blocks")

  println("[PASS] Test 4: IRGen if")
  return true
}

# ----------------------------------------------------------------
# Test 5: IR 생성기 — while 루프
# ----------------------------------------------------------------

fn test_irgen_while() {
  println("=== Test 5: IRGen - while loop ===")

  # fn sum_to(n) {
  #   i = 0
  #   s = 0
  #   while i < n {
  #     s = s + i
  #     i = i + 1
  #   }
  #   return s
  # }

  sum_ast = {
    "type": "functionDefinition",
    "name": "sum_to",
    "params": ["n"],
    "body": [
      { "type": "assignment", "variable": "i",
        "value": { "type": "literal", "literalType": "int", "value": 0 } },
      { "type": "assignment", "variable": "s",
        "value": { "type": "literal", "literalType": "int", "value": 0 } },
      {
        "type": "whileStatement",
        "condition": {
          "type": "binaryOp", "operator": "<",
          "left":  { "type": "identifier", "name": "i" },
          "right": { "type": "identifier", "name": "n" }
        },
        "body": [
          { "type": "assignment", "variable": "s",
            "value": {
              "type": "binaryOp", "operator": "+",
              "left":  { "type": "identifier", "name": "s" },
              "right": { "type": "identifier", "name": "i" }
            }
          },
          { "type": "assignment", "variable": "i",
            "value": {
              "type": "binaryOp", "operator": "+",
              "left":  { "type": "identifier", "name": "i" },
              "right": { "type": "literal", "literalType": "int", "value": 1 }
            }
          }
        ]
      },
      { "type": "returnStatement",
        "value": { "type": "identifier", "name": "s" } }
    ]
  }

  ir_mod = irgen_module("test_while", [sum_ast])
  ir_text = ir_module_to_str(ir_mod)
  println(ir_text)

  fns = ir_mod["functions"]
  assert(len(fns) == 1, "one function")
  blocks = fns[0]["blocks"]
  # while → loop_cond + loop_body + loop_exit + entry = 최소 4개
  assert(len(blocks) >= 4, "while generates 4+ blocks")

  println("[PASS] Test 5: IRGen while")
  return true
}

# ----------------------------------------------------------------
# assert 유틸
# ----------------------------------------------------------------

fn assert(cond, msg) {
  if not cond {
    println("FAIL: " + msg)
    return false
  }
  return true
}

# ----------------------------------------------------------------
# 메인
# ----------------------------------------------------------------

fn main() {
  println("Free IR 1.0 — Node & Generator Tests")
  println("========================================")

  r1 = test_types()
  r2 = test_manual_ir()
  r3 = test_irgen_add()
  r4 = test_irgen_if()
  r5 = test_irgen_while()

  passed = 0
  if r1 { passed = passed + 1 }
  if r2 { passed = passed + 1 }
  if r3 { passed = passed + 1 }
  if r4 { passed = passed + 1 }
  if r5 { passed = passed + 1 }

  println("========================================")
  println("Results: " + str(passed) + "/5 PASS")

  if passed == 5 {
    println("IR 1.0 FOUNDATION COMPLETE")
  }
}

