# ================================================================
# Free IR 1.0 — IR Generator
# AST (FreeLang 파서 출력) → Free IR
#
# 입력: parser.fl 출력 AST 노드
# 출력: ir_node.fl 구조
# ================================================================

# ----------------------------------------------------------------
# 빌더 상태 (불변 함수형 스타일 — context 전달)
# ----------------------------------------------------------------

fn irgen_context(module, current_func, current_block, blocks, reg_count, label_count) {
  return {
    "module":        module,
    "current_func":  current_func,   # 현재 작성 중인 함수 이름
    "current_block": current_block,  # 현재 basic block
    "blocks":        blocks,         # 완성된 블록 목록
    "reg_count":     reg_count,      # SSA 레지스터 카운터
    "label_count":   label_count,    # 레이블 카운터
    "locals":        {},             # 변수명 → alloca ptr val 매핑
    "func_sigs":     {}              # 함수명 → { params, ret_type } 매핑
  }
}

fn irgen_fresh(module_name) {
  mod = ir_module(module_name)
  return irgen_context(mod, "", ir_block("__init__", []), [], 0, 0)
}

# 새 SSA 이름 생성
fn irgen_new_reg(ctx) {
  name = "r" + str(ctx["reg_count"])
  new_ctx = {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": ctx["current_block"],
    "blocks":        ctx["blocks"],
    "reg_count":     ctx["reg_count"] + 1,
    "label_count":   ctx["label_count"],
    "locals":        ctx["locals"],
    "func_sigs":     ctx["func_sigs"]
  }
  return { "name": name, "ctx": new_ctx }
}

# 새 레이블 생성
fn irgen_new_label(ctx, prefix) {
  name = prefix + str(ctx["label_count"])
  new_ctx = {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": ctx["current_block"],
    "blocks":        ctx["blocks"],
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"] + 1,
    "locals":        ctx["locals"],
    "func_sigs":     ctx["func_sigs"]
  }
  return { "name": name, "ctx": new_ctx }
}

# 현재 블록에 instruction 추가
fn irgen_emit(ctx, inst) {
  new_block = ir_block_add_inst(ctx["current_block"], inst)
  return {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": new_block,
    "blocks":        ctx["blocks"],
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"],
    "locals":        ctx["locals"],
    "func_sigs":     ctx["func_sigs"]
  }
}

# 현재 블록을 마무리하고 새 블록 시작
fn irgen_seal_and_start(ctx, new_label) {
  sealed_blocks = append(ctx["blocks"], ctx["current_block"])
  new_block = ir_block(new_label, [])
  return {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": new_block,
    "blocks":        sealed_blocks,
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"],
    "locals":        ctx["locals"],
    "func_sigs":     ctx["func_sigs"]
  }
}

# 지역 변수 등록
fn irgen_set_local(ctx, var_name, ptr_val) {
  new_locals = map_set(ctx["locals"], var_name, ptr_val)
  return {
    "module":        ctx["module"],
    "current_func":  ctx["current_func"],
    "current_block": ctx["current_block"],
    "blocks":        ctx["blocks"],
    "reg_count":     ctx["reg_count"],
    "label_count":   ctx["label_count"],
    "locals":        new_locals,
    "func_sigs":     ctx["func_sigs"]
  }
}

# ----------------------------------------------------------------
# AST 타입 → IR 타입 변환
# ----------------------------------------------------------------

fn irgen_resolve_type(type_str) {
  if type_str == "i8"   { return ir_type_i8() }
  if type_str == "i16"  { return ir_type_i16() }
  if type_str == "i32"  { return ir_type_i32() }
  if type_str == "i64"  { return ir_type_i64() }
  if type_str == "u8"   { return ir_type_u8() }
  if type_str == "u16"  { return ir_type_u16() }
  if type_str == "u32"  { return ir_type_u32() }

# ================================================================
# Free IR 1.0 — Reference Interpreter
# IR → 실행 결과 (정확성 100% 목표, 속도 무관)
#
# 역할: IR의 의미 보존 증명
# 이후: codegen 결과와 diff 비교로 self-verification
# ================================================================

# ----------------------------------------------------------------
# 1. 실행 환경 (Environment)
# ----------------------------------------------------------------

# 인터프리터 상태
fn interp_env(regs, memory, mem_ptr, call_stack, globals) {
  # regs       : { reg_name → value }      SSA 레지스터 값
  # memory     : [value, ...]               선형 메모리 (alloca/store/load)
  # mem_ptr    : i64                        다음 할당 주소
  # call_stack : [frame, ...]               호출 스택
  # globals    : { name → value }           전역 심볼
  return {
    "regs":       regs,
    "memory":     memory,
    "mem_ptr":    mem_ptr,
    "call_stack": call_stack,
    "globals":    globals
  }
}

fn interp_env_fresh(globals) {
  return interp_env({}, [], 0, [], globals)
}

# 레지스터 읽기
fn env_get_reg(env, name) {
  v = env["regs"][name]
  if v == null { return 0 }
  return v
}

# 레지스터 쓰기
fn env_set_reg(env, name, value) {
  new_regs = map_set(env["regs"], name, value)
  return {
    "regs":       new_regs,
    "memory":     env["memory"],
    "mem_ptr":    env["mem_ptr"],
    "call_stack": env["call_stack"],
    "globals":    env["globals"]
  }
}

# 메모리 alloca (주소 반환)
fn env_alloca(env, size) {
  addr = env["mem_ptr"]
  new_ptr = addr + size
  # 메모리 배열을 0으로 패딩 확장
  new_mem = env["memory"]
  i = len(new_mem)
  while i < new_ptr {
    new_mem = append(new_mem, 0)
    i = i + 1
  }
  new_env = {
    "regs":       env["regs"],
    "memory":     new_mem,
    "mem_ptr":    new_ptr,
    "call_stack": env["call_stack"],
    "globals":    env["globals"]
  }
  return { "addr": addr, "env": new_env }
}

# 메모리 load (주소 → 값)
fn env_load(env, addr) {
  mem = env["memory"]
  if addr < 0 or addr >= len(mem) { return 0 }
  return mem[addr]
}

# 메모리 store (주소 ← 값)

