		for i, inc := range inst.Incoming {
			parts[i] = fmt.Sprintf("[%s, %%%s]", inc.Val, inc.Block)
		}
		return fmt.Sprintf("%%%s = phi %s %s",
			inst.Result, inst.Type, strings.Join(parts, ", "))
	}
	return "unknown"
}

