// Free IR 1.0 — Reference Interpreter
// 정확성 100% 목표. 속도 무관.
package interp

import (
	"fmt"
	"fir/src/ir"
	"math"
)

// ----------------------------------------------------------------
// Value (런타임 값)
// ----------------------------------------------------------------

type RVal struct {
	I int64
	F float64
	IsFloat bool
}

func rInt(v int64) RVal   { return RVal{I: v} }
func rFloat(v float64) RVal { return RVal{F: v, IsFloat: true} }

func (r RVal) AsInt() int64 {
	if r.IsFloat { return int64(r.F) }
	return r.I
}
func (r RVal) AsFloat() float64 {
	if r.IsFloat { return r.F }
	return float64(r.I)
}
func (r RVal) Bool() bool { return r.I != 0 }

// ----------------------------------------------------------------
// Env (실행 환경)
// ----------------------------------------------------------------

type Env struct {
	Regs    map[string]RVal
	Memory  []RVal
	MemPtr  int
	Globals map[string]RVal
	FuncMap map[string]*ir.Function
}

func newEnv(globals map[string]RVal, funcMap map[string]*ir.Function) *Env {
	return &Env{
		Regs:    make(map[string]RVal),
		Memory:  make([]RVal, 0, 256),
		MemPtr:  0,
		Globals: globals,
		FuncMap: funcMap,
	}
}

func (e *Env) getReg(name string) RVal {
	if v, ok := e.Regs[name]; ok { return v }
	return rInt(0)
}

func (e *Env) setReg(name string, v RVal) {
	e.Regs[name] = v
}

func (e *Env) alloca(size int) int {
	if size < 1 { size = 1 }
	addr := e.MemPtr
	e.MemPtr += size
	for len(e.Memory) < e.MemPtr {
		e.Memory = append(e.Memory, rInt(0))
	}
	return addr
}

func (e *Env) load(addr int) RVal {
	if addr < 0 || addr >= len(e.Memory) { return rInt(0) }
	return e.Memory[addr]
}

func (e *Env) store(addr int, v RVal) {
	for len(e.Memory) <= addr {
		e.Memory = append(e.Memory, rInt(0))
	}
	e.Memory[addr] = v
}

// ----------------------------------------------------------------
// 값 평가
// ----------------------------------------------------------------

func evalVal(env *Env, v *ir.Value) RVal {
	switch v.Kind {
	case ir.ValConstInt:
		return rInt(v.IVal)
	case ir.ValConstFloat:
		return rFloat(v.FVal)
	case ir.ValConstBool:
		if v.BVal { return rInt(1) }
		return rInt(0)
	case ir.ValConstNull:
		return rInt(0)
	case ir.ValReg:
		return env.getReg(v.Name)
	case ir.ValGlobalRef:
		if gv, ok := env.Globals[v.Name]; ok { return gv }
		return rInt(0)
	}
	return rInt(0)
}

// ----------------------------------------------------------------
// 신호 타입
// ----------------------------------------------------------------

type Signal int
const (
	SigContinue Signal = iota
	SigBranch
	SigReturn
)

type Result struct {
	Sig    Signal
	Label  string // branch target
	RetVal RVal
}

// ----------------------------------------------------------------
// Instruction 실행
// ----------------------------------------------------------------

func execInst(env *Env, inst *ir.Inst) Result {
	switch inst.Kind {

	// --- 산술/논리 ---
	case ir.InstBinop:
		lv := evalVal(env, inst.LHS)
		rv := evalVal(env, inst.RHS)
		var res RVal
		switch inst.Op {
		case "add":  res = rInt(lv.AsInt() + rv.AsInt())
		case "sub":  res = rInt(lv.AsInt() - rv.AsInt())
		case "mul":  res = rInt(lv.AsInt() * rv.AsInt())
		case "div":
			if rv.AsInt() == 0 { res = rInt(0) } else { res = rInt(lv.AsInt() / rv.AsInt()) }
		case "rem":
			if rv.AsInt() == 0 { res = rInt(0) } else { res = rInt(lv.AsInt() % rv.AsInt()) }
		case "and":  res = rInt(lv.AsInt() & rv.AsInt())
		case "or":   res = rInt(lv.AsInt() | rv.AsInt())
		case "xor":  res = rInt(lv.AsInt() ^ rv.AsInt())
		case "shl":  res = rInt(lv.AsInt() << uint(rv.AsInt()))
		case "shr":  res = rInt(lv.AsInt() >> uint(rv.AsInt()))
		case "fadd": res = rFloat(lv.AsFloat() + rv.AsFloat())
		case "fsub": res = rFloat(lv.AsFloat() - rv.AsFloat())
		case "fmul": res = rFloat(lv.AsFloat() * rv.AsFloat())
		case "fdiv":
			if rv.AsFloat() == 0 { res = rFloat(math.NaN()) } else { res = rFloat(lv.AsFloat() / rv.AsFloat()) }
		default:     res = rInt(0)
		}
		env.setReg(inst.Result, res)

	case ir.InstNeg:
		v := evalVal(env, inst.Operand)
		env.setReg(inst.Result, rInt(-v.AsInt()))

	// --- 비교 ---
	case ir.InstICmp:
		lv := evalVal(env, inst.LHS).AsInt()
		rv := evalVal(env, inst.RHS).AsInt()
		var cmp bool
		switch inst.Pred {
		case "eq":  cmp = lv == rv
		case "ne":  cmp = lv != rv
		case "lt":  cmp = lv < rv
		case "le":  cmp = lv <= rv
		case "gt":  cmp = lv > rv
		case "ge":  cmp = lv >= rv
		case "ult": cmp = uint64(lv) < uint64(rv)
		case "ule": cmp = uint64(lv) <= uint64(rv)
		case "ugt": cmp = uint64(lv) > uint64(rv)
		case "uge": cmp = uint64(lv) >= uint64(rv)
		}
		if cmp { env.setReg(inst.Result, rInt(1)) } else { env.setReg(inst.Result, rInt(0)) }

	case ir.InstFCmp:
		lv := evalVal(env, inst.LHS).AsFloat()
		rv := evalVal(env, inst.RHS).AsFloat()
		var cmp bool
		switch inst.Pred {
		case "oeq": cmp = lv == rv
		case "one": cmp = lv != rv
		case "olt": cmp = lv < rv
		case "ole": cmp = lv <= rv
		case "ogt": cmp = lv > rv
		case "oge": cmp = lv >= rv
		}
		if cmp { env.setReg(inst.Result, rInt(1)) } else { env.setReg(inst.Result, rInt(0)) }

	// --- 메모리 ---
	case ir.InstAlloca:
		size := inst.AllocType.Size
		if size < 1 { size = 1 }
		addr := env.alloca(size)
		env.setReg(inst.Result, rInt(int64(addr)))

	case ir.InstLoad:
		ptr := evalVal(env, inst.Ptr).AsInt()
		env.setReg(inst.Result, env.load(int(ptr)))

	case ir.InstStore:
		ptr := evalVal(env, inst.Ptr).AsInt()
		val := evalVal(env, inst.Val)
		env.store(int(ptr), val)

	case ir.InstGEP:
		base := evalVal(env, inst.Ptr).AsInt()
		idx  := evalVal(env, inst.Idx).AsInt()
		stride := int64(inst.ElemType.Size)
		if stride < 1 { stride = 1 }
		env.setReg(inst.Result, rInt(base+idx*stride))

	// --- 캐스트 ---
	case ir.InstCast:
		v := evalVal(env, inst.Operand)
		var res RVal
		switch inst.Op {
		case "trunc":
			iv := v.AsInt()
			switch inst.ToType.Name {
			case "i8",  "u8":  iv &= 0xFF
			case "i16", "u16": iv &= 0xFFFF
			case "i32", "u32": iv &= 0xFFFFFFFF
			}
			res = rInt(iv)
		case "zext", "sext":          res = rInt(v.AsInt())
		case "fpext", "fptrunc":       res = rFloat(v.AsFloat())
		case "fptosi":                 res = rInt(int64(v.AsFloat()))
		case "sitofp":                 res = rFloat(float64(v.AsInt()))
		case "bitcast", "ptrtoint", "inttoptr": res = v
		default:                       res = v
		}
		env.setReg(inst.Result, res)

	// --- 호출 ---
	case ir.InstCall:
		args := make([]RVal, len(inst.Args))
		for i, a := range inst.Args { args[i] = evalVal(env, a) }

		calleeName := ""
		switch inst.Callee.Kind {
		case ir.ValGlobalRef: calleeName = inst.Callee.Name
		case ir.ValReg:       calleeName = fmt.Sprintf("%d", env.getReg(inst.Callee.Name).AsInt())
		}

		var retVal RVal
		if isBuiltin(calleeName) {
			retVal = execBuiltin(calleeName, args)
		} else if fn, ok := env.FuncMap[calleeName]; ok {
			retVal = ExecFunction(fn, args, env.Globals, env.FuncMap)
		}
		// extern stub → 0

		if inst.Result != "" {
			env.setReg(inst.Result, retVal)
		}

	// --- 제어 흐름 ---
	case ir.InstBr:
		return Result{Sig: SigBranch, Label: inst.Target}

	case ir.InstBrCond:
		cond := evalVal(env, inst.Cond)
		if cond.Bool() {
			return Result{Sig: SigBranch, Label: inst.TrueLabel}
		}
		return Result{Sig: SigBranch, Label: inst.FalseLabel}

	case ir.InstRet:
		return Result{Sig: SigReturn, RetVal: evalVal(env, inst.Val)}

	case ir.InstRetVoid:
		return Result{Sig: SigReturn, RetVal: rInt(0)}

	case ir.InstPhi:
		// phi는 execBlock에서 선처리됨 — pass

	}
	return Result{Sig: SigContinue}
}

// ----------------------------------------------------------------
// Block 실행
// ----------------------------------------------------------------

func execBlock(env *Env, block *ir.Block, prevLabel string) Result {
	// Pass 1: phi 동시 평가
	phiNames := []string{}
	phiVals  := []RVal{}
	for _, inst := range block.Insts {
		if inst.Kind == ir.InstPhi {
			v := evalPhi(env, inst, prevLabel)
			phiNames = append(phiNames, inst.Result)
			phiVals  = append(phiVals, v)
		}
	}
	for i, name := range phiNames {
		env.setReg(name, phiVals[i])
	}

	// Pass 2: 나머지 실행
	for _, inst := range block.Insts {
		if inst.Kind == ir.InstPhi { continue }
		r := execInst(env, inst)
		if r.Sig != SigContinue { return r }
	}

	return Result{Sig: SigReturn, RetVal: rInt(0)} // 비정상 종료
}

func evalPhi(env *Env, inst *ir.Inst, prevLabel string) RVal {
	for _, inc := range inst.Incoming {
		if inc.Block == prevLabel {
			return evalVal(env, inc.Val)
		}
	}
	return rInt(0)
}

// ----------------------------------------------------------------
// 함수 실행
// ----------------------------------------------------------------

func ExecFunction(fn *ir.Function, args []RVal, globals map[string]RVal, funcMap map[string]*ir.Function) RVal {
	env := newEnv(globals, funcMap)

	// 파라미터 바인딩
	for i, p := range fn.Params {
		if i < len(args) {
			env.setReg(p.Name, args[i])
		}
	}

	// 블록 맵
	blockMap := make(map[string]*ir.Block)
	for _, b := range fn.Blocks { blockMap[b.Label] = b }

	cur  := "entry"
	prev := ""
	const maxSteps = 100000

	for step := 0; step < maxSteps; step++ {
		b, ok := blockMap[cur]
		if !ok { return rInt(0) }

		r := execBlock(env, b, prev)
		if r.Sig == SigReturn { return r.RetVal }
		if r.Sig == SigBranch {
			prev = cur
			cur  = r.Label
		}
	}
	return rInt(0)
}

// ----------------------------------------------------------------
// 모듈 실행 (진입점)
// ----------------------------------------------------------------

func ExecModule(mod *ir.Module, entryName string, args []RVal) (RVal, error) {
	globals := make(map[string]RVal)
	for _, g := range mod.Globals {
		switch v := g.Init.(type) {
		case int64:   globals[g.Name] = rInt(v)
		case float64: globals[g.Name] = rFloat(v)
		case int:     globals[g.Name] = rInt(int64(v))
		}
	}

	funcMap := mod.FuncMap()

	fn, ok := funcMap[entryName]
	if !ok {
		return rInt(0), fmt.Errorf("entry function not found: %s", entryName)
	}

	return ExecFunction(fn, args, globals, funcMap), nil
}

// ----------------------------------------------------------------
// Builtin
// ----------------------------------------------------------------

func isBuiltin(name string) bool {
	switch name {
	case "println", "print", "abs", "max", "min", "printf", "malloc", "free":
		return true
	}
	return false
}

func execBuiltin(name string, args []RVal) RVal {
	switch name {
	case "println":
		if len(args) > 0 { fmt.Println(args[0].AsInt()) }
		return rInt(0)
	case "print":
		if len(args) > 0 { fmt.Print(args[0].AsInt()) }
		return rInt(0)
	case "abs":
		v := args[0].AsInt()
		if v < 0 { return rInt(-v) }
		return rInt(v)
	case "max":
		if args[0].AsInt() > args[1].AsInt() { return args[0] }
		return args[1]
	case "min":
		if args[0].AsInt() < args[1].AsInt() { return args[0] }
		return args[1]
	}
	return rInt(0)
}

