// Free IR 1.0 — Code Generator
// IR → x86-64 (Linux ELF64, System V ABI)
// 정확성 우선. 최적화 없음.
package codegen

import (
	"encoding/binary"
	"fmt"
	"fir/src/ir"
)

// ----------------------------------------------------------------
// 레지스터 정의 (x86-64 System V ABI)
// ----------------------------------------------------------------

type Reg byte

const (
	RAX Reg = 0
	RCX Reg = 1
	RDX Reg = 2
	RBX Reg = 3
	RSP Reg = 4
	RBP Reg = 5
	RSI Reg = 6
	RDI Reg = 7
	R8  Reg = 8
	R9  Reg = 9
	R10 Reg = 10
	R11 Reg = 11
	R12 Reg = 12
	R13 Reg = 13
	R14 Reg = 14
	R15 Reg = 15
)

// 인자 전달 레지스터 (System V ABI)
var argRegs = []Reg{RDI, RSI, RDX, RCX, R8, R9}

// ----------------------------------------------------------------
// Assembler (x86-64 명령어 인코더)
// ----------------------------------------------------------------

type Asm struct {
	buf    []byte
	labels map[string]int32       // label → offset
	fixups []fixup                // 미해결 분기
}

type fixup struct {
	offset int    // 패치할 위치 (disp32 시작)
	label  string // 목표 레이블
}

func NewAsm() *Asm {
	return &Asm{labels: make(map[string]int32)}
}

func (a *Asm) Len() int { return len(a.buf) }
func (a *Asm) Bytes() []byte { return a.buf }

func (a *Asm) emit(b ...byte) { a.buf = append(a.buf, b...) }

func (a *Asm) emit32(v int32) {
	var b [4]byte
	binary.LittleEndian.PutUint32(b[:], uint32(v))
	a.buf = append(a.buf, b[:]...)
}

func (a *Asm) emit64(v int64) {
	var b [8]byte
	binary.LittleEndian.PutUint64(b[:], uint64(v))
	a.buf = append(a.buf, b[:]...)
}

// MarkLabel: 현재 위치에 레이블 기록
func (a *Asm) MarkLabel(name string) {
	a.labels[name] = int32(len(a.buf))
}

// ResolveFixups: 모든 미결 분기를 패치
func (a *Asm) ResolveFixups() error {
	for _, f := range a.fixups {
		target, ok := a.labels[f.label]
		if !ok {
			return fmt.Errorf("unresolved label: %s", f.label)
		}
		// rel32 = target - (patch_pos + 4)
		rel := target - int32(f.offset+4)
		binary.LittleEndian.PutUint32(a.buf[f.offset:], uint32(rel))
	}
	return nil
}

// ----------------------------------------------------------------
// x86-64 명령어 인코딩
// ----------------------------------------------------------------

// REX prefix: W=1(64bit), R=reg>=8, X=0, B=rm>=8
func rex(w bool, r, rm Reg) byte {
	var b byte = 0x40
	if w      { b |= 0x08 }
	if r >= 8  { b |= 0x04 }
	if rm >= 8 { b |= 0x01 }
	return b
}

// ModRM: mod=11(reg), reg, rm
func modrm(mod byte, r, rm Reg) byte {
	return mod<<6 | (byte(r)&7)<<3 | (byte(rm)&7)
}

// MOV reg, reg (64bit)
func (a *Asm) MovRR(dst, src Reg) {
	a.emit(rex(true, src, dst), 0x89, modrm(0b11, src, dst))
}

// MOV reg, imm64
func (a *Asm) MovRI(dst Reg, imm int64) {
	a.emit(rex(true, 0, dst), 0xB8|byte(dst&7))
	a.emit64(imm)
}

// MOV reg, imm32 (부호 확장)
func (a *Asm) MovRI32(dst Reg, imm int32) {
	a.emit(rex(true, 0, dst), 0xC7, modrm(0b11, 0, dst))
	a.emit32(imm)
}

// MOV [rbp+off], reg (store to stack)
func (a *Asm) StoreStack(off int32, src Reg) {
	a.emit(rex(true, src, RBP), 0x89)
	a.emit(0x85 | (byte(src&7) << 3)) // ModRM: mod=10, reg=src, rm=RBP
	a.emit32(off)
}

// MOV reg, [rbp+off] (load from stack)
func (a *Asm) LoadStack(dst Reg, off int32) {
	a.emit(rex(true, dst, RBP), 0x8B)
	a.emit(0x85 | (byte(dst&7) << 3))
	a.emit32(off)
}

// ADD dst, src
func (a *Asm) AddRR(dst, src Reg) {
	a.emit(rex(true, src, dst), 0x01, modrm(0b11, src, dst))
}

// SUB dst, src
func (a *Asm) SubRR(dst, src Reg) {
	a.emit(rex(true, src, dst), 0x29, modrm(0b11, src, dst))
}

// IMUL dst, src
func (a *Asm) IMulRR(dst, src Reg) {
	a.emit(rex(true, dst, src), 0x0F, 0xAF, modrm(0b11, dst, src))
}

// IDIV src (rax / src → rax 몫, rdx 나머지)
func (a *Asm) IDiv(src Reg) {
	a.emit(rex(true, 0, src), 0xF7, modrm(0b11, 7, src))
}

// CQO (rdx:rax 부호 확장)
func (a *Asm) CQO() { a.emit(0x48, 0x99) }

// CMP dst, src
func (a *Asm) CmpRR(dst, src Reg) {
	a.emit(rex(true, src, dst), 0x39, modrm(0b11, src, dst))
}

// CMP dst, imm32
func (a *Asm) CmpRI(dst Reg, imm int32) {
	a.emit(rex(true, 0, dst), 0x81, modrm(0b11, 7, dst))
	a.emit32(imm)
}

// SETcc al (조건 코드 → 0/1)
func (a *Asm) Setcc(cc byte) {
	a.emit(0x40, 0x0F, cc, 0xC0) // setcc al (REX + 0F cc /0)
}

// MOVZX rax, al (1바이트 → 64bit 0확장)
func (a *Asm) MovzxAL() {
	a.emit(0x48, 0x0F, 0xB6, 0xC0)
}

// AND dst, imm32
func (a *Asm) AndRI(dst Reg, imm int32) {
	a.emit(rex(true, 0, dst), 0x81, modrm(0b11, 4, dst))
	a.emit32(imm)
}

// NEG dst
func (a *Asm) NegR(dst Reg) {
	a.emit(rex(true, 0, dst), 0xF7, modrm(0b11, 3, dst))
}

// PUSH reg
func (a *Asm) Push(r Reg) {
	if r >= 8 { a.emit(0x41) }
	a.emit(0x50 | byte(r&7))
}

// POP reg
func (a *Asm) Pop(r Reg) {
	if r >= 8 { a.emit(0x41) }
	a.emit(0x58 | byte(r&7))
}

// SUB rsp, imm32 (스택 확보)
func (a *Asm) SubSP(size int32) {
	a.emit(0x48, 0x81, 0xEC)
	a.emit32(size)
}

// ADD rsp, imm32 (스택 해제)
func (a *Asm) AddSP(size int32) {
	a.emit(0x48, 0x81, 0xC4)
	a.emit32(size)
}

// RET
func (a *Asm) Ret() { a.emit(0xC3) }

// CALL rel32
func (a *Asm) Call(label string) {
	a.emit(0xE8)
	a.fixups = append(a.fixups, fixup{offset: len(a.buf), label: label})
	a.emit32(0) // placeholder
}

// JMP rel32
func (a *Asm) Jmp(label string) {
	a.emit(0xE9)
	a.fixups = append(a.fixups, fixup{offset: len(a.buf), label: label})
	a.emit32(0)
}

// JE / JNE / JL / JLE / JG / JGE rel32
func (a *Asm) Jcc(cc byte, label string) {
	a.emit(0x0F, cc)
	a.fixups = append(a.fixups, fixup{offset: len(a.buf), label: label})
	a.emit32(0)
}

const (
	JE  = byte(0x84)
	JNE = byte(0x85)
	JL  = byte(0x8C)
	JLE = byte(0x8E)
	JG  = byte(0x8F)
	JGE = byte(0x8D)
	JB  = byte(0x82) // unsigned <
	JBE = byte(0x86)
	JA  = byte(0x87) // unsigned >
	JAE = byte(0x83)
)

// ----------------------------------------------------------------
// 함수 컴파일러
// ----------------------------------------------------------------

type FuncCompiler struct {
	fn      *ir.Function
	asm     *Asm
	// SSA 값 → 스택 슬롯 (rbp 기준 음수 offset)
	slots   map[string]int32
	nextOff int32 // 다음 슬롯 offset (음수 방향)
	funcMap map[string]string // fn name → label
}

func newFuncCompiler(fn *ir.Function, funcMap map[string]string) *FuncCompiler {
	return &FuncCompiler{
		fn:      fn,
		asm:     NewAsm(),
		slots:   make(map[string]int32),
		nextOff: 0,
		funcMap: funcMap,
	}
}

func (fc *FuncCompiler) slot(name string) int32 {
	if off, ok := fc.slots[name]; ok { return off }
	fc.nextOff -= 8
	fc.slots[name] = fc.nextOff
	return fc.nextOff
}

func (fc *FuncCompiler) stackSize() int32 {
	// 16바이트 정렬
	size := -fc.nextOff
	if size%16 != 0 { size = (size/16 + 1) * 16 }
	if size == 0    { size = 16 }
	return size
}

// 값을 RAX에 로드
func (fc *FuncCompiler) loadToRAX(v *ir.Value) {
	switch v.Kind {
	case ir.ValConstInt:
		fc.asm.MovRI(RAX, v.IVal)
	case ir.ValConstBool:
		if v.BVal { fc.asm.MovRI32(RAX, 1) } else { fc.asm.MovRI32(RAX, 0) }
	case ir.ValConstNull:
		fc.asm.MovRI32(RAX, 0)
	case ir.ValReg:
		off := fc.slot(v.Name)
		fc.asm.LoadStack(RAX, off)
	case ir.ValGlobalRef:
		// 함수 포인터는 Phase 1에서 call 시 이름으로 처리
		fc.asm.MovRI32(RAX, 0)
	}
}

// 값을 특정 레지스터에 로드
func (fc *FuncCompiler) loadToReg(reg Reg, v *ir.Value) {
	fc.loadToRAX(v)
	if reg != RAX { fc.asm.MovRR(reg, RAX) }
}

// RAX를 슬롯에 저장
func (fc *FuncCompiler) storeRAX(name string) {
	off := fc.slot(name)
	fc.asm.StoreStack(off, RAX)
}

// ----------------------------------------------------------------
// Instruction 컴파일
// ----------------------------------------------------------------

func (fc *FuncCompiler) compileInst(inst *ir.Inst) error {
	switch inst.Kind {

	case ir.InstBinop:
		fc.loadToRAX(inst.LHS)
		fc.asm.StoreStack(fc.slot("__tmp_lhs__"), RAX)
		fc.loadToRAX(inst.RHS)
		fc.asm.MovRR(RCX, RAX) // RCX = rhs
		fc.asm.LoadStack(RAX, fc.slot("__tmp_lhs__")) // RAX = lhs

		switch inst.Op {
		case "add":
			fc.asm.AddRR(RAX, RCX)
		case "sub":
			fc.asm.SubRR(RAX, RCX)
		case "mul":
			fc.asm.IMulRR(RAX, RCX)
		case "div":
			fc.asm.CQO()
			fc.asm.IDiv(RCX)
		case "rem":
			fc.asm.CQO()
			fc.asm.IDiv(RCX)
			fc.asm.MovRR(RAX, RDX) // 나머지는 RDX
		case "and":
			fc.asm.emit(rex(true, RCX, RAX), 0x21, modrm(0b11, RCX, RAX))
		case "or":
			fc.asm.emit(rex(true, RCX, RAX), 0x09, modrm(0b11, RCX, RAX))
		case "xor":
			fc.asm.emit(rex(true, RCX, RAX), 0x31, modrm(0b11, RCX, RAX))
		}
		fc.storeRAX(inst.Result)

	case ir.InstNeg:
		fc.loadToRAX(inst.Operand)
		fc.asm.NegR(RAX)
		fc.storeRAX(inst.Result)

	case ir.InstICmp:
		fc.loadToRAX(inst.LHS)
		fc.asm.StoreStack(fc.slot("__tmp_lhs__"), RAX)
		fc.loadToRAX(inst.RHS)
		fc.asm.MovRR(RCX, RAX)
		fc.asm.LoadStack(RAX, fc.slot("__tmp_lhs__"))
		fc.asm.CmpRR(RAX, RCX)

		// SETcc → al → RAX
		var cc byte
		switch inst.Pred {
		case "eq":  cc = 0x94 // SETE
		case "ne":  cc = 0x95 // SETNE
		case "lt":  cc = 0x9C // SETL
		case "le":  cc = 0x9E // SETLE
		case "gt":  cc = 0x9F // SETG
		case "ge":  cc = 0x9D // SETGE
		case "ult": cc = 0x92 // SETB
		case "ule": cc = 0x96 // SETBE
		case "ugt": cc = 0x97 // SETA
		case "uge": cc = 0x93 // SETAE
		default:    cc = 0x94
		}
		fc.asm.emit(0x0F, cc, 0xC0) // SETcc al
		fc.asm.MovzxAL()
		fc.storeRAX(inst.Result)

	case ir.InstAlloca:
		// alloca: nextOff에서 슬롯 할당, 주소(rbp+off)를 결과에 저장
		off := fc.slot(inst.Result + "__alloca__")
		// LEA rax, [rbp+off]
		fc.asm.emit(rex(true, RAX, RBP), 0x8D, 0x85|byte(RAX&7)<<3)
		fc.asm.emit32(off)
		fc.storeRAX(inst.Result)

	case ir.InstLoad:
		// ptr 값 = 스택 주소 → [ptr]에서 로드
		fc.loadToRAX(inst.Ptr)
		fc.asm.MovRR(RCX, RAX)
		// MOV rax, [rcx]
		fc.asm.emit(rex(true, RAX, RCX), 0x8B, modrm(0b00, RAX, RCX))
		fc.storeRAX(inst.Result)

	case ir.InstStore:
		fc.loadToRAX(inst.Val)
		fc.asm.MovRR(RCX, RAX)       // RCX = value
		fc.loadToRAX(inst.Ptr)       // RAX = ptr
		fc.asm.MovRR(RDX, RAX)       // RDX = ptr
		// MOV [rdx], rcx
		fc.asm.emit(rex(true, RCX, RDX), 0x89, modrm(0b00, RCX, RDX))

	case ir.InstCast:
		fc.loadToRAX(inst.Operand)
		switch inst.Op {
		case "trunc":
			switch inst.ToType.Name {
			case "i8",  "u8":  fc.asm.AndRI(RAX, 0xFF)
			case "i16", "u16": fc.asm.AndRI(RAX, 0xFFFF)
			case "i32", "u32": fc.asm.AndRI(RAX, int32(0xFFFFFFFF))
			}
		}
		fc.storeRAX(inst.Result)

	case ir.InstCall:
		// 인자를 ABI 레지스터에 배치
		for i, arg := range inst.Args {
			if i >= len(argRegs) { break } // 스택 인자는 Phase 2
			fc.loadToReg(argRegs[i], arg)
		}
		calleeName := ""
		if inst.Callee.Kind == ir.ValGlobalRef { calleeName = inst.Callee.Name }
		label := fc.fn.Name + "__call__" + calleeName
		if l, ok := fc.funcMap[calleeName]; ok { label = l }
		fc.asm.Call(label)
		if inst.Result != "" {
			fc.storeRAX(inst.Result)
		}

	case ir.InstBr:
		fc.asm.Jmp(fc.fn.Name + "__" + inst.Target)

	case ir.InstBrCond:
		fc.loadToRAX(inst.Cond)
		fc.asm.CmpRI(RAX, 0)
		fc.asm.Jcc(JNE, fc.fn.Name+"__"+inst.TrueLabel)
		fc.asm.Jmp(fc.fn.Name + "__" + inst.FalseLabel)

	case ir.InstRet:
		fc.loadToRAX(inst.Val)
		// epilogue
		fc.emitEpilogue()
		fc.asm.Ret()

	case ir.InstRetVoid:
		fc.asm.MovRI32(RAX, 0)
		fc.emitEpilogue()
		fc.asm.Ret()

	case ir.InstPhi:
		// phi는 predecessor 블록 끝에서 처리 (Phase 1: mem-based)
		// 인터프리터처럼 블록 진입 시 처리하는 대신
		// 여기서는 스택 슬롯에 이미 올바른 값이 있다고 가정
		// (irgen이 alloca+store+load로 내린 경우 phi 불필요)
	}
	return nil
}

func (fc *FuncCompiler) emitEpilogue() {
	// MOV rsp, rbp; POP rbp
	fc.asm.MovRR(RSP, RBP)
	fc.asm.Pop(RBP)
}

// ----------------------------------------------------------------
// 함수 컴파일
// ----------------------------------------------------------------

func (fc *FuncCompiler) Compile() error {
	fn := fc.fn
	a  := fc.asm

	// 1패스: 스택 크기 결정을 위해 모든 슬롯 미리 등록
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Result != "" { fc.slot(inst.Result) }
		}
	}
	// 파라미터 슬롯
	for _, p := range fn.Params { fc.slot(p.Name) }
	// 임시 슬롯
	fc.slot("__tmp_lhs__")

	frameSize := fc.stackSize()

	// prologue
	a.Push(RBP)
	a.MovRR(RBP, RSP)
	a.SubSP(frameSize)

	// 파라미터 → 스택 슬롯
	for i, p := range fn.Params {
		if i < len(argRegs) {
			a.StoreStack(fc.slot(p.Name), argRegs[i])
		}
	}

	// 블록 컴파일
	for _, b := range fn.Blocks {
		a.MarkLabel(fn.Name + "__" + b.Label)
		for _, inst := range b.Insts {
			if err := fc.compileInst(inst); err != nil { return err }
		}
	}

	return a.ResolveFixups()
}

// ----------------------------------------------------------------
// 모듈 컴파일러
// ----------------------------------------------------------------

type CompiledModule struct {
	Code     []byte            // 전체 코드 섹션
	FuncOff  map[string]int    // 함수명 → 코드 내 오프셋
	FuncSize map[string]int
}

func CompileModule(mod *ir.Module) (*CompiledModule, error) {
	cm := &CompiledModule{
		FuncOff:  make(map[string]int),
		FuncSize: make(map[string]int),
	}

	// 함수 레이블 맵 (이름 → 레이블 접두사)
	funcLabels := make(map[string]string)
	for _, fn := range mod.Functions {
		funcLabels[fn.Name] = fn.Name + "__entry"
	}

	// 각 함수 컴파일
	for _, fn := range mod.Functions {
		fc := newFuncCompiler(fn, funcLabels)
		if err := fc.Compile(); err != nil {
			return nil, fmt.Errorf("compile %s: %w", fn.Name, err)
		}

		off := len(cm.Code)
		cm.FuncOff[fn.Name]  = off
		cm.FuncSize[fn.Name] = fc.asm.Len()
		cm.Code = append(cm.Code, fc.asm.Bytes()...)
	}

	return cm, nil
}

// ELF64 바이너리 생성기
// Linux x86-64 실행 파일 (.elf) 생성
package codegen

import (
	"encoding/binary"
	"bytes"
)

const (
	elfHeaderSize   = 64
	phdrSize        = 56
	baseAddr  uint64 = 0x400000
	pageSize  uint64 = 0x1000
)

// ELF64 헤더
func elf64Header(entry, phoff, phnum uint64) []byte {
	var b [64]byte
	// Magic
	copy(b[0:], []byte{0x7f, 'E', 'L', 'F'})
	b[4] = 2    // 64-bit
	b[5] = 1    // little-endian
	b[6] = 1    // ELF version
	b[7] = 0    // OS/ABI: System V
	// e_type = ET_EXEC (2)
	binary.LittleEndian.PutUint16(b[16:], 2)
	// e_machine = EM_X86_64 (0x3e)
	binary.LittleEndian.PutUint16(b[18:], 0x3e)
	// e_version = 1
	binary.LittleEndian.PutUint32(b[20:], 1)
	// e_entry
	binary.LittleEndian.PutUint64(b[24:], entry)
	// e_phoff
	binary.LittleEndian.PutUint64(b[32:], phoff)
	// e_shoff = 0 (no sections)
	// e_flags = 0
	// e_ehsize = 64
	binary.LittleEndian.PutUint16(b[52:], 64)
	// e_phentsize = 56
	binary.LittleEndian.PutUint16(b[54:], 56)
	// e_phnum
	binary.LittleEndian.PutUint16(b[56:], uint16(phnum))
	// e_shentsize = 64
	binary.LittleEndian.PutUint16(b[58:], 64)
	return b[:]
}

// PT_LOAD 프로그램 헤더 (RX: 실행 세그먼트)
func elf64Phdr(offset, vaddr, filesz, memsz, flags uint64) []byte {
	var b [56]byte
	binary.LittleEndian.PutUint32(b[0:], 1)       // PT_LOAD
	binary.LittleEndian.PutUint32(b[4:], flags)   // PF_R|PF_X = 5
	binary.LittleEndian.PutUint64(b[8:], offset)
	binary.LittleEndian.PutUint64(b[16:], vaddr)
	binary.LittleEndian.PutUint64(b[24:], vaddr)  // paddr = vaddr
	binary.LittleEndian.PutUint64(b[32:], filesz)
	binary.LittleEndian.PutUint64(b[40:], memsz)
	binary.LittleEndian.PutUint64(b[48:], pageSize)
	return b[:]
}

// BuildELF: 코드 섹션 + 진입 오프셋 → ELF64 바이너리
func BuildELF(code []byte, entryOffset int) []byte {
	// 레이아웃:
	//   [ELF header 64B][Phdr 56B][code ...]
	headerSize := uint64(elfHeaderSize + phdrSize)
	fileSize   := headerSize + uint64(len(code))
	entryVA    := baseAddr + headerSize + uint64(entryOffset)

	var buf bytes.Buffer
	buf.Write(elf64Header(entryVA, elfHeaderSize, 1))
	buf.Write(elf64Phdr(0, baseAddr, fileSize, fileSize, 5)) // PF_R|PF_X
	buf.Write(code)
	return buf.Bytes()
}

// BuildELFWithSyscallExit: exit syscall stub을 포함한 바이너리
// main 함수 반환값 → exit(rax)
func BuildELFWithEntry(code []byte, entryOffset int) []byte {
	// _start stub: call main, mov rdi,rax, mov rax,60, syscall
	stub := []byte{
		// call main (rel32 placeholder → 패치 필요)
		0xE8, 0x00, 0x00, 0x00, 0x00,
		// mov rdi, rax
		0x48, 0x89, 0xC7,
		// xor rax, rax; mov eax, 60 (sys_exit)
		0x48, 0xC7, 0xC0, 0x3C, 0x00, 0x00, 0x00,
		// syscall
		0x0F, 0x05,
	}

	// call main의 rel32 패치
	// stub 시작 = code 뒤
	// main offset = entryOffset (code 내)
	// call 위치 = len(code) + 0 (stub 시작)
	// call 다음 = len(code) + 5
	// rel = entryOffset - (len(code) + 5)
	rel := int32(entryOffset - (len(code) + 5))
	binary.LittleEndian.PutUint32(stub[1:], uint32(rel))

	combined := append(code, stub...)
	startOffset := len(code) // _start는 stub 시작

	return BuildELF(combined, startOffset)
}

