	for _, b := range fn.Blocks {
		a.MarkLabel(fn.Name + "__" + b.Label)
		for _, inst := range b.Insts {
			if err := fc.compileInst(inst); err != nil { return err }
		}
	}

	return a.ResolveFixups()
}

// ----------------------------------------------------------------
// 모듈 컴파일러
// ----------------------------------------------------------------

type CompiledModule struct {
	Code     []byte            // 전체 코드 섹션
	FuncOff  map[string]int    // 함수명 → 코드 내 오프셋
	FuncSize map[string]int
}

func CompileModule(mod *ir.Module) (*CompiledModule, error) {
	cm := &CompiledModule{
		FuncOff:  make(map[string]int),
		FuncSize: make(map[string]int),
	}

	// 함수 레이블 맵 (이름 → 레이블 접두사)
	funcLabels := make(map[string]string)
	for _, fn := range mod.Functions {
		funcLabels[fn.Name] = fn.Name + "__entry"
	}

	// 각 함수 컴파일
	for _, fn := range mod.Functions {
		fc := newFuncCompiler(fn, funcLabels)
		if err := fc.Compile(); err != nil {
			return nil, fmt.Errorf("compile %s: %w", fn.Name, err)
		}

		off := len(cm.Code)
		cm.FuncOff[fn.Name]  = off
		cm.FuncSize[fn.Name] = fc.asm.Len()
		cm.Code = append(cm.Code, fc.asm.Bytes()...)

