		fc.loadToRAX(inst.Ptr)
		fc.asm.MovRR(RCX, RAX)
		// MOV rax, [rcx]
		fc.asm.emit(rex(true, RAX, RCX), 0x8B, modrm(0b00, RAX, RCX))
		fc.storeRAX(inst.Result)

	case ir.InstStore:
		fc.loadToRAX(inst.Val)
		fc.asm.MovRR(RCX, RAX)       // RCX = value
		fc.loadToRAX(inst.Ptr)       // RAX = ptr
		fc.asm.MovRR(RDX, RAX)       // RDX = ptr
		// MOV [rdx], rcx
		fc.asm.emit(rex(true, RCX, RDX), 0x89, modrm(0b00, RCX, RDX))

	case ir.InstCast:
		fc.loadToRAX(inst.Operand)
		switch inst.Op {
		case "trunc":
			switch inst.ToType.Name {
			case "i8",  "u8":  fc.asm.AndRI(RAX, 0xFF)
			case "i16", "u16": fc.asm.AndRI(RAX, 0xFFFF)
			case "i32", "u32": fc.asm.AndRI(RAX, int32(-1))
			}
		}
		fc.storeRAX(inst.Result)

	case ir.InstCall:
		// 인자를 먼저 스택에 스필(spill)한 후 ABI 레지스터로 이동
		// 이유: loadToRAX가 내부적으로 RAX를 경유하므로
		//       레지스터에 직접 쓰면 앞 인자가 덮힐 수 있음
		spillSlots := make([]int32, len(inst.Args))
		for i, arg := range inst.Args {
			if i >= len(argRegs) { break }
			fc.loadToRAX(arg)
			spillName := fmt.Sprintf("__call_spill_%d__", i)
			off := fc.slot(spillName)
			fc.asm.StoreStack(off, RAX)
			spillSlots[i] = off
		}
		// 스필된 값을 ABI 레지스터로 이동
		for i := range inst.Args {
			if i >= len(argRegs) { break }
			fc.asm.LoadStack(argRegs[i], spillSlots[i])
		}
		calleeName := ""
		if inst.Callee.Kind == ir.ValGlobalRef { calleeName = inst.Callee.Name }
		label := calleeName + "__entry"
		if l, ok := fc.funcMap[calleeName]; ok { label = l }
		fc.asm.Call(label)
		if inst.Result != "" {
			fc.storeRAX(inst.Result)
		}

	case ir.InstBr:
		fc.asm.Jmp(fc.fn.Name + "__" + inst.Target)

	case ir.InstBrCond:
		fc.loadToRAX(inst.Cond)
		fc.asm.CmpRI(RAX, 0)
		fc.asm.Jcc(JNE, fc.fn.Name+"__"+inst.TrueLabel)
		fc.asm.Jmp(fc.fn.Name + "__" + inst.FalseLabel)

	case ir.InstRet:
		fc.loadToRAX(inst.Val)
		// epilogue
		fc.emitEpilogue()
		fc.asm.Ret()

	case ir.InstRetVoid:
		fc.asm.MovRI32(RAX, 0)
		fc.emitEpilogue()
		fc.asm.Ret()

	case ir.InstPhi:
		// phi는 predecessor 블록 끝에서 처리 (Phase 1: mem-based)
		// 인터프리터처럼 블록 진입 시 처리하는 대신
		// 여기서는 스택 슬롯에 이미 올바른 값이 있다고 가정
		// (irgen이 alloca+store+load로 내린 경우 phi 불필요)
	}
	return nil
}

func (fc *FuncCompiler) emitEpilogue() {
	// MOV rsp, rbp; POP rbp
	fc.asm.MovRR(RSP, RBP)
	fc.asm.Pop(RBP)
}

