func testNativeFloatOps() {
	fmt.Println("--- Codegen Test: float ops (fadd/fsub/fmul/fdiv/fcmp) ---")

	type floatCase struct {
		name   string
		buildMod func() *ir.Module
		expect int64
	}

	// ConstFloat를 저장할 때: float64 비트 패턴을 int64로 재해석
	// interp는 FVal로 처리, codegen은 IVal 비트 패턴을 xmm으로 MOVQ
	floatBits := func(f float64) *ir.Value {
		return ir.ConstFloat(f, ir.F64())
	}

	cases := []floatCase{
		{
			name: "fadd 1.5+2.5=4",
			buildMod: func() *ir.Module {
				entry := ir.NewBlock("entry")
				entry.Add(ir.NewBinop("fadd", "r", ir.F64(), floatBits(1.5), floatBits(2.5)))
				entry.Add(ir.NewCast("fptosi", "i", ir.F64(), ir.Reg("r", ir.F64()), ir.I64()))
				entry.Add(ir.NewRet(ir.Reg("i", ir.I64())))
				fn := ir.NewFunction("fop", nil, ir.I64(), true)
				fn.AddBlock(entry)
				mod := ir.NewModule("fadd")
				mod.AddFunction(fn)
				return mod
			},
			expect: 4,
		},
		{
			name: "fsub 10.0-3.0=7",
			buildMod: func() *ir.Module {
				entry := ir.NewBlock("entry")
				entry.Add(ir.NewBinop("fsub", "r", ir.F64(), floatBits(10.0), floatBits(3.0)))
				entry.Add(ir.NewCast("fptosi", "i", ir.F64(), ir.Reg("r", ir.F64()), ir.I64()))
				entry.Add(ir.NewRet(ir.Reg("i", ir.I64())))
				fn := ir.NewFunction("fop", nil, ir.I64(), true)
				fn.AddBlock(entry)
				mod := ir.NewModule("fsub")
				mod.AddFunction(fn)
				return mod
			},
			expect: 7,
		},
		{
			name: "fmul 3.0*4.0=12",
			buildMod: func() *ir.Module {
				entry := ir.NewBlock("entry")
				entry.Add(ir.NewBinop("fmul", "r", ir.F64(), floatBits(3.0), floatBits(4.0)))
				entry.Add(ir.NewCast("fptosi", "i", ir.F64(), ir.Reg("r", ir.F64()), ir.I64()))
				entry.Add(ir.NewRet(ir.Reg("i", ir.I64())))
				fn := ir.NewFunction("fop", nil, ir.I64(), true)
				fn.AddBlock(entry)
				mod := ir.NewModule("fmul")
				mod.AddFunction(fn)
				return mod
			},
			expect: 12,
		},
		{
			name: "fdiv 15.0/3.0=5",
			buildMod: func() *ir.Module {
				entry := ir.NewBlock("entry")
				entry.Add(ir.NewBinop("fdiv", "r", ir.F64(), floatBits(15.0), floatBits(3.0)))
				entry.Add(ir.NewCast("fptosi", "i", ir.F64(), ir.Reg("r", ir.F64()), ir.I64()))
				entry.Add(ir.NewRet(ir.Reg("i", ir.I64())))
				fn := ir.NewFunction("fop", nil, ir.I64(), true)
				fn.AddBlock(entry)
				mod := ir.NewModule("fdiv")
				mod.AddFunction(fn)
				return mod
			},
			expect: 5,
		},
		{
			name: "fcmp olt 1.0<2.0=1",
			buildMod: func() *ir.Module {
				entry := ir.NewBlock("entry")
				entry.Add(ir.NewFCmp("olt", "c", ir.F64(), floatBits(1.0), floatBits(2.0)))
				entry.Add(ir.NewRet(ir.Reg("c", ir.Bool())))
				fn := ir.NewFunction("fop", nil, ir.I64(), true)
				fn.AddBlock(entry)
				mod := ir.NewModule("fcmp_lt")
				mod.AddFunction(fn)
				return mod
			},
			expect: 1,
		},
		{
			name: "fcmp ogt 3.0>1.0=1",
			buildMod: func() *ir.Module {
				entry := ir.NewBlock("entry")
				entry.Add(ir.NewFCmp("ogt", "c", ir.F64(), floatBits(3.0), floatBits(1.0)))
				entry.Add(ir.NewRet(ir.Reg("c", ir.Bool())))
				fn := ir.NewFunction("fop", nil, ir.I64(), true)
				fn.AddBlock(entry)
				mod := ir.NewModule("fcmp_gt")
				mod.AddFunction(fn)
				return mod
			},
			expect: 1,
		},
		{
			name: "sitofp+fmul: 3*4.0=12",
			buildMod: func() *ir.Module {
				entry := ir.NewBlock("entry")
				entry.Add(ir.NewCast("sitofp", "fv", ir.I64(), ir.ConstInt(3, ir.I64()), ir.F64()))
				entry.Add(ir.NewBinop("fmul", "r", ir.F64(), ir.Reg("fv", ir.F64()), floatBits(4.0)))
				entry.Add(ir.NewCast("fptosi", "i", ir.F64(), ir.Reg("r", ir.F64()), ir.I64()))
				entry.Add(ir.NewRet(ir.Reg("i", ir.I64())))
				fn := ir.NewFunction("fop", nil, ir.I64(), true)
				fn.AddBlock(entry)
				mod := ir.NewModule("sitofp")
				mod.AddFunction(fn)
				return mod
			},
			expect: 12,
		},
	}

	for _, tc := range cases {
		mod := tc.buildMod()

		// interp
		ir_r, err := interp.ExecModule(mod, "fop", nil)
		if err != nil { fmt.Printf("[FAIL] %s interp: %v\n", tc.name, err); cgFailed++; continue }
		interpVal := ir_r.AsInt()

		// native
		cm, err := codegen.CompileModule(mod)
		if err != nil { fmt.Printf("[FAIL] %s compile: %v\n", tc.name, err); cgFailed++; continue }
		off := cm.FuncOff["fop"]
		elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
		nativeVal, err := execElf(elfBytes)
		if err != nil { fmt.Printf("[SKIP] %s: %v\n", tc.name, err); continue }

		if interpVal == tc.expect && nativeVal == tc.expect {
			fmt.Printf("[PASS] %s: interp=%d native=%d\n", tc.name, interpVal, nativeVal)
			cgPassed++
		} else {
			fmt.Printf("[FAIL] %s: interp=%d native=%d (expected %d)\n",
				tc.name, interpVal, nativeVal, tc.expect)
			cgFailed++
		}
	}
}

func runCodegenTests() {
	fmt.Println()
	fmt.Println("=== Codegen Tests ===")

	testCodegenIRText()
	testCodegenBuild()
	testNativeRet()
	testDiff()
	testNativeCall()
	testNativeIntOps()
	testNativeFloatOps()

