// codegen 검증 테스트
// native 결과 == interp 결과 확인
package main

import (
	"fmt"
	"fir/src/codegen"
	"fir/src/interp"
	"fir/src/ir"
	"os"
	"os/exec"
	"strconv"
	"strings"
)

// ----------------------------------------------------------------
// native 실행: ELF 바이너리를 파일로 쓰고 실행
// ----------------------------------------------------------------

// execElf: ELF 바이너리를 실행하고 exit code 반환
// ARM64에서는 qemu-x86_64 사용
func execElf(elfBytes []byte) (int64, error) {
	f, err := os.CreateTemp("", "fir_*.elf")
	if err != nil { return 0, err }
	defer os.Remove(f.Name())
	f.Write(elfBytes)
	f.Close()
	os.Chmod(f.Name(), 0755)

	var cmd *exec.Cmd
	arch := getArch()
	if arch != "x86_64" {
		qemu, err2 := exec.LookPath("qemu-x86_64")
		if err2 != nil { return 0, fmt.Errorf("qemu-x86_64 not found (arch=%s)", arch) }
		cmd = exec.Command(qemu, f.Name())
	} else {
		cmd = exec.Command(f.Name())
	}

	err = cmd.Run()
	if err != nil {
		if ee, ok := err.(*exec.ExitError); ok {
			return int64(ee.ExitCode()), nil
		}
		return 0, err
	}
	return 0, nil
}

func runNative(mod *ir.Module, entryName string) (int64, error) {
	cm, err := codegen.CompileModule(mod)
	if err != nil { return 0, fmt.Errorf("compile: %w", err) }

	off, ok := cm.FuncOff[entryName]
	if !ok { return 0, fmt.Errorf("entry not found: %s", entryName) }

	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
	return execElf(elfBytes)
}

// ----------------------------------------------------------------
// diff 검증: interp 결과 == codegen exit code
// ----------------------------------------------------------------

var cgPassed, cgFailed int

func assertNativeEq(label string, mod *ir.Module, entryName string, args []interp.RVal, expected int64) {
	// interp 결과
	ir_result, err := interp.ExecModule(mod, entryName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | interp error: %v\n", label, err)
		cgFailed++
		return
	}

	// native 결과
	cm, err := codegen.CompileModule(mod)
	if err != nil {
		fmt.Printf("[FAIL] %s | codegen error: %v\n", label, err)
		cgFailed++
		return
	}

	off, ok := cm.FuncOff[entryName]
	if !ok {
		fmt.Printf("[FAIL] %s | entry not found\n", label)
		cgFailed++
		return
	}

	// ELF 실행
	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
	exitCode, err := execElf(elfBytes)
	if err != nil {
		fmt.Printf("[SKIP] %s native: %v\n", label, err)
		return
	}

	interpVal := ir_result.AsInt()

	if interpVal == expected && exitCode == expected {
		fmt.Printf("[PASS] %s | interp=%d native=%d\n", label, interpVal, exitCode)
		cgPassed++
	} else if interpVal != expected {
		fmt.Printf("[FAIL] %s | interp=%d (expected %d)\n", label, interpVal, expected)
		cgFailed++
	} else {
		fmt.Printf("[FAIL] %s | native=%d (expected %d, interp=%d)\n", label, exitCode, expected, interpVal)
		cgFailed++
	}
}

// ----------------------------------------------------------------
// IR 텍스트 출력 검증
// ----------------------------------------------------------------

func testCodegenIRText() {
	fmt.Println("--- Codegen Test: IR text ---")
	params := []ir.Param{{Name: "x", Type: ir.I64()}}
	entry := ir.NewBlock("entry")
	entry.Add(ir.NewBinop("add", "r0", ir.I64(), ir.Reg("x", ir.I64()), ir.ConstInt(1, ir.I64())))
	entry.Add(ir.NewRet(ir.Reg("r0", ir.I64())))

	fn := ir.NewFunction("inc", params, ir.I64(), true)
	fn.AddBlock(entry)
	mod := ir.NewModule("cg_text")
	mod.AddFunction(fn)

	text := mod.String()
	if strings.Contains(text, "export fn @inc") && strings.Contains(text, "add i64") {
		fmt.Println("[PASS] IR text contains expected output")
		cgPassed++
	} else {
		fmt.Printf("[FAIL] IR text unexpected:\n%s\n", text)
		cgFailed++
	}
}

// ----------------------------------------------------------------
// 코드젠 바이너리 생성 확인 (실행 없이 크기 검증)
// ----------------------------------------------------------------

func testCodegenBuild() {
	fmt.Println("--- Codegen Test: binary build ---")

	// fn ret42() -> i64 { return 42 }
	entry := ir.NewBlock("entry")
	entry.Add(ir.NewRet(ir.ConstInt(42, ir.I64())))
	fn := ir.NewFunction("ret42", nil, ir.I64(), true)
	fn.AddBlock(entry)
	mod := ir.NewModule("cg_build")
	mod.AddFunction(fn)

	cm, err := codegen.CompileModule(mod)
	if err != nil {
		fmt.Printf("[FAIL] compile: %v\n", err)
		cgFailed++
		return
	}

	if len(cm.Code) > 0 {
		fmt.Printf("[PASS] binary generated: %d bytes\n", len(cm.Code))
		cgPassed++
	} else {
		fmt.Println("[FAIL] empty binary")
		cgFailed++
	}

	// ELF 생성
	off := cm.FuncOff["ret42"]
	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
	if len(elfBytes) >= 120 { // header(64) + phdr(56) + code
		fmt.Printf("[PASS] ELF generated: %d bytes\n", len(elfBytes))
		cgPassed++
	} else {
		fmt.Printf("[FAIL] ELF too small: %d bytes\n", len(elfBytes))
		cgFailed++
	}
}

// ----------------------------------------------------------------
// native 실행 검증 (exit code = 반환값)
// ----------------------------------------------------------------

func testNativeRet() {
	fmt.Println("--- Codegen Test: native exit code ---")

	// fn main() -> i64 { return 7 }
	entry := ir.NewBlock("entry")
	entry.Add(ir.NewRet(ir.ConstInt(7, ir.I64())))
	fn := ir.NewFunction("main", nil, ir.I64(), true)
	fn.AddBlock(entry)
	mod := ir.NewModule("cg_native")
	mod.AddFunction(fn)

	cm, err := codegen.CompileModule(mod)
	if err != nil {
		fmt.Printf("[SKIP] compile: %v\n", err)
		return
	}

	off := cm.FuncOff["main"]
	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)

	exitCode, err := execElf(elfBytes)
	if err != nil {
		fmt.Printf("[FAIL] native exec: %v\n", err)
		cgFailed++
		return
	}

	if exitCode == 7 {
		fmt.Printf("[PASS] native exit code == 7\n")
		cgPassed++
	} else {
		fmt.Printf("[FAIL] native exit code == %d (expected 7)\n", exitCode)
		cgFailed++
	}
}

// ----------------------------------------------------------------
// interp == native diff 검증
// ----------------------------------------------------------------

func testDiff() {
	fmt.Println("--- Codegen Test: interp == native diff ---")

	// fn add(a,b) { return a+b } — 인자는 환경 변수로 전달 불가
	// 대신 상수 함수로 검증
	cases := []struct {
		name     string
		retVal   int64
	}{
		{"zero", 0},
		{"one",  1},
		{"ten",  10},
	}

	for _, tc := range cases {
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewRet(ir.ConstInt(tc.retVal, ir.I64())))
		fn := ir.NewFunction("fn_"+tc.name, nil, ir.I64(), true)
		fn.AddBlock(entry)
		mod := ir.NewModule("diff_" + tc.name)
		mod.AddFunction(fn)

		// interp
		ir_r, _ := interp.ExecModule(mod, "fn_"+tc.name, nil)
		interpVal := ir_r.AsInt()

		// native
		cm, err := codegen.CompileModule(mod)
		if err != nil {
			fmt.Printf("[SKIP] %s compile: %v\n", tc.name, err)
			continue
		}
		off := cm.FuncOff["fn_"+tc.name]
		elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
		nativeVal, err := execElf(elfBytes)
		if err != nil {
			fmt.Printf("[SKIP] %s native: %v\n", tc.name, err)
			continue
		}

		if interpVal == tc.retVal && nativeVal == tc.retVal {
			fmt.Printf("[PASS] %s: interp=%d native=%d\n", tc.name, interpVal, nativeVal)
			cgPassed++
		} else {
			fmt.Printf("[FAIL] %s: interp=%d native=%d (expected %d)\n",
				tc.name, interpVal, nativeVal, tc.retVal)
			cgFailed++
		}
	}
}

// ----------------------------------------------------------------
// 함수 호출 네이티브 검증
// ----------------------------------------------------------------

func testNativeCall() {
	fmt.Println("--- Codegen Test: native function call ---")

	// fn id(x i64) -> i64 { return x }
	// main calls id(5), exit(result) → exit code 5
	{
		idParams := []ir.Param{{Name: "x", Type: ir.I64()}}
		idEntry := ir.NewBlock("entry")
		idEntry.Add(ir.NewRet(ir.Reg("x", ir.I64())))
		idFn := ir.NewFunction("id", idParams, ir.I64(), false)
		idFn.AddBlock(idEntry)

		mainEntry := ir.NewBlock("entry")
		mainEntry.Add(ir.NewCall("r", ir.I64(), ir.GlobalRef("id", ir.I64()), []*ir.Value{ir.ConstInt(5, ir.I64())}))
		mainEntry.Add(ir.NewRet(ir.Reg("r", ir.I64())))
		mainFn := ir.NewFunction("main", nil, ir.I64(), true)
		mainFn.AddBlock(mainEntry)

		mod := ir.NewModule("call_id")
		mod.AddFunction(idFn)
		mod.AddFunction(mainFn)

		cm, err := codegen.CompileModule(mod)
		if err != nil { fmt.Printf("[FAIL] id compile: %v\n", err); cgFailed++; goto addTest }
		{
			off := cm.FuncOff["main"]
			elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
			exitCode, err := execElf(elfBytes)
			if err != nil { fmt.Printf("[SKIP] id native: %v\n", err); goto addTest }
			if exitCode == 5 {
				fmt.Printf("[PASS] call id(5) == 5\n"); cgPassed++
			} else {
				fmt.Printf("[FAIL] call id(5): got=%d expected=5\n", exitCode); cgFailed++
			}
		}
	}
addTest:
	// fn add(a,b i64) -> i64 { return a+b }
	// main calls add(3,4) → exit code 7
	{
		addParams := []ir.Param{{Name: "a", Type: ir.I64()}, {Name: "b", Type: ir.I64()}}
		addEntry := ir.NewBlock("entry")
		addEntry.Add(ir.NewBinop("add", "r", ir.I64(), ir.Reg("a", ir.I64()), ir.Reg("b", ir.I64())))
		addEntry.Add(ir.NewRet(ir.Reg("r", ir.I64())))
		addFn := ir.NewFunction("add_fn", addParams, ir.I64(), false)
		addFn.AddBlock(addEntry)

		mainEntry := ir.NewBlock("entry")
		mainEntry.Add(ir.NewCall("r", ir.I64(), ir.GlobalRef("add_fn", ir.I64()),
			[]*ir.Value{ir.ConstInt(3, ir.I64()), ir.ConstInt(4, ir.I64())}))
		mainEntry.Add(ir.NewRet(ir.Reg("r", ir.I64())))
		mainFn := ir.NewFunction("main2", nil, ir.I64(), true)
		mainFn.AddBlock(mainEntry)

		mod := ir.NewModule("call_add")
		mod.AddFunction(addFn)
		mod.AddFunction(mainFn)

		cm, err := codegen.CompileModule(mod)
		if err != nil { fmt.Printf("[FAIL] add compile: %v\n", err); cgFailed++; return }
		off := cm.FuncOff["main2"]
		elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
		exitCode, err := execElf(elfBytes)
		if err != nil { fmt.Printf("[SKIP] add native: %v\n", err); return }
		if exitCode == 7 {
			fmt.Printf("[PASS] call add(3,4) == 7\n"); cgPassed++
		} else {
			fmt.Printf("[FAIL] call add(3,4): got=%d expected=7\n", exitCode); cgFailed++
		}
	}
}

func runCodegenTests() {
	fmt.Println()
	fmt.Println("=== Codegen Tests ===")

	testCodegenIRText()
	testCodegenBuild()
	testNativeRet()
	testDiff()
	testNativeCall()

	fmt.Println()
	fmt.Printf("Codegen Results: %d/%d PASS\n", cgPassed, cgPassed+cgFailed)

	if cgFailed == 0 {
		fmt.Println()
		fmt.Println("CODEGEN VERIFIED")
		fmt.Println("native == interp")
	} else {
		// 일부 실패는 ARM64 환경 예상 — 메시지 출력
		arch := getArch()
		fmt.Printf("(arch: %s — x86-64 native tests may skip on non-x86)\n", arch)
	}
}

func getArch() string {
	out, err := exec.Command("uname", "-m").Output()
	if err != nil { return "unknown" }
	return strings.TrimSpace(string(out))
}

