	l.advance()
	switch ch {
	case '+': return Token{Kind: TokPlus,    Lit: "+", Line: line}
	case '*': return Token{Kind: TokStar,    Lit: "*", Line: line}
	case '%': return Token{Kind: TokPercent, Lit: "%", Line: line}
	case '^': return Token{Kind: TokCaret,   Lit: "^", Line: line}
	case '(': return Token{Kind: TokLParen,  Lit: "(", Line: line}
	case ')': return Token{Kind: TokRParen,  Lit: ")", Line: line}
	case '{': return Token{Kind: TokLBrace,  Lit: "{", Line: line}
	case '}': return Token{Kind: TokRBrace,  Lit: "}", Line: line}
	case '[': return Token{Kind: TokLBracket,Lit: "[", Line: line}
	case ']': return Token{Kind: TokRBracket,Lit: "]", Line: line}
	case ':': return Token{Kind: TokColon,   Lit: ":", Line: line}
	case ';': return Token{Kind: TokSemi,    Lit: ";", Line: line}
	case ',': return Token{Kind: TokComma,   Lit: ",", Line: line}
	case '.': return Token{Kind: TokDot,     Lit: ".", Line: line}
	case '-':
		if l.peek() == '>' { l.advance(); return Token{Kind: TokArrow, Lit: "->", Line: line} }
		return Token{Kind: TokMinus, Lit: "-", Line: line}
	case '/':
		return Token{Kind: TokSlash, Lit: "/", Line: line}
	case '&':
		if l.peek() == '&' { l.advance(); return Token{Kind: TokAmpAmp, Lit: "&&", Line: line} }
		return Token{Kind: TokAmp, Lit: "&", Line: line}
	case '|':
		if l.peek() == '|' { l.advance(); return Token{Kind: TokPipePipe, Lit: "||", Line: line} }
		return Token{Kind: TokPipe, Lit: "|", Line: line}
	case '!':
		if l.peek() == '=' { l.advance(); return Token{Kind: TokBangEq, Lit: "!=", Line: line} }
		return Token{Kind: TokBang, Lit: "!", Line: line}
	case '=':
		if l.peek() == '=' { l.advance(); return Token{Kind: TokEqEq, Lit: "==", Line: line} }
		return Token{Kind: TokEq, Lit: "=", Line: line}
	case '<':
		if l.peek() == '=' { l.advance(); return Token{Kind: TokLtEq, Lit: "<=", Line: line} }
		if l.peek() == '<' { l.advance(); return Token{Kind: TokLtLt, Lit: "<<", Line: line} }
		return Token{Kind: TokLt, Lit: "<", Line: line}
	case '>':
		if l.peek() == '=' { l.advance(); return Token{Kind: TokGtEq, Lit: ">=", Line: line} }
		if l.peek() == '>' { l.advance(); return Token{Kind: TokGtGt, Lit: ">>", Line: line} }
		return Token{Kind: TokGt, Lit: ">", Line: line}
	}
	return Token{Kind: TokEOF, Lit: string(ch), Line: line}
}

func (l *Lexer) lexNumber(line int) Token {
	var sb strings.Builder
	isFloat := false
	for l.pos < len(l.src) {
		ch := l.peek()
		if unicode.IsDigit(ch) {
			sb.WriteRune(l.advance())
		} else if ch == '.' && !isFloat && unicode.IsDigit(l.peek2()) {
			isFloat = true
			sb.WriteRune(l.advance())
		} else {
			break
		}
	}
	if isFloat {
		return Token{Kind: TokFloat, Lit: sb.String(), Line: line}
	}
	return Token{Kind: TokInt, Lit: sb.String(), Line: line}
}

func (l *Lexer) lexIdent(line int) Token {
	var sb strings.Builder
	for l.pos < len(l.src) {
		ch := l.peek()
		if unicode.IsLetter(ch) || unicode.IsDigit(ch) || ch == '_' {
			sb.WriteRune(l.advance())
		} else {
			break
		}
	}
	lit := sb.String()
	if kind, ok := keywords[lit]; ok {
		return Token{Kind: kind, Lit: lit, Line: line}
	}
	return Token{Kind: TokIdent, Lit: lit, Line: line}
}

func (l *Lexer) lexString(line int) Token {
	l.advance() // 여는 "
	var sb strings.Builder
	for l.pos < len(l.src) {
		ch := l.advance()
		if ch == '"' { break }
		if ch == '\\' && l.pos < len(l.src) {
			esc := l.advance()
			switch esc {
			case 'n': sb.WriteRune('\n')
			case 't': sb.WriteRune('\t')
			default:  sb.WriteRune(esc)
			}
			continue
		}
		sb.WriteRune(ch)
	}
	return Token{Kind: TokString, Lit: sb.String(), Line: line}
}

// Tokenize: 전체 토큰 배열 반환
func Tokenize(src string) []Token {
	l := NewLexer(src)
	var toks []Token
	for {
		t := l.Next()
		toks = append(toks, t)
		if t.Kind == TokEOF { break }
	}
	return toks
}

