	ExprInt    ExprKind = iota // 42
	ExprFloat                  // 3.14
	ExprBool                   // true / false
	ExprIdent                  // foo
	ExprBinop                  // a + b
	ExprUnary                  // -x, !x
	ExprCall                   // f(a, b)
	ExprCast                   // x as i32
	ExprString                 // "hello"
)

type Expr struct {
	Kind   ExprKind
	// Int/Float/Bool/String/Ident
	IVal   int64
	FVal   float64
	BVal   bool
	SVal   string
	// Binop
	Op     string
	Left   *Expr
	Right  *Expr
	// Unary
	Operand *Expr
	// Call
	Callee string
	Args   []*Expr
	// Cast
	ToType *AstType
}

