// 최상위 선언 (Top-level)
// ----------------------------------------------------------------

type Param struct {
	Name string
	Type *AstType
}

type FnDecl struct {
	Name     string
	Params   []Param
	RetType  *AstType
	Body     []*Stmt
	IsExtern bool   // extern fn
}

type Program struct {
	Fns []*FnDecl
}

