// FreeLang → Free IR — Parser
// 토큰 스트림 → AST
package irgen

import (
	"fmt"
	"strconv"
)

// ----------------------------------------------------------------
// Parser
// ----------------------------------------------------------------

type Parser struct {
	toks []Token
	pos  int
}

func NewParser(toks []Token) *Parser {
	return &Parser{toks: toks, pos: 0}
}

func (p *Parser) peek() Token {
	if p.pos >= len(p.toks) { return Token{Kind: TokEOF} }
	return p.toks[p.pos]
}

func (p *Parser) peek2() Token {
	if p.pos+1 >= len(p.toks) { return Token{Kind: TokEOF} }
	return p.toks[p.pos+1]
}

func (p *Parser) advance() Token {
	t := p.toks[p.pos]
	p.pos++
	return t
}

func (p *Parser) expect(kind TokKind) (Token, error) {
	t := p.peek()
	if t.Kind != kind {
		return t, fmt.Errorf("line %d: expected token %d, got %q", t.Line, kind, t.Lit)
	}
	return p.advance(), nil
}

func (p *Parser) check(kind TokKind) bool {
	return p.peek().Kind == kind
}

func (p *Parser) eat(kind TokKind) bool {
	if p.check(kind) { p.advance(); return true }
	return false
}

// ----------------------------------------------------------------
// Program
// ----------------------------------------------------------------

func ParseProgram(src string) (*Program, error) {
	toks := Tokenize(src)
	p := NewParser(toks)
	return p.parseProgram()
}

func (p *Parser) parseProgram() (*Program, error) {
	prog := &Program{}
	for !p.check(TokEOF) {
		// 세미콜론 건너뛰기
		if p.eat(TokSemi) { continue }

		fn, err := p.parseFnDecl()
		if err != nil { return nil, err }
		prog.Fns = append(prog.Fns, fn)
	}
	return prog, nil
}

// ----------------------------------------------------------------
// 함수 선언
// ----------------------------------------------------------------

func (p *Parser) parseFnDecl() (*FnDecl, error) {
	isExtern := p.eat(TokExtern)

	if _, err := p.expect(TokFn); err != nil { return nil, err }

	nameTok, err := p.expect(TokIdent)
	if err != nil { return nil, err }

	if _, err := p.expect(TokLParen); err != nil { return nil, err }

	params, err := p.parseParams()
	if err != nil { return nil, err }

	if _, err := p.expect(TokRParen); err != nil { return nil, err }

	// -> RetType
	var retType *AstType
	if p.eat(TokArrow) {
		retType, err = p.parseType()
		if err != nil { return nil, err }
	} else {
		retType = &AstType{Name: "void"}
	}

	if isExtern {
		p.eat(TokSemi) // extern fn 선언은 바디 없음
		return &FnDecl{
			Name: nameTok.Lit, Params: params, RetType: retType, IsExtern: true,
		}, nil
	}

	body, err := p.parseBlock()
	if err != nil { return nil, err }

	return &FnDecl{
		Name: nameTok.Lit, Params: params, RetType: retType, Body: body,
	}, nil
}

func (p *Parser) parseParams() ([]Param, error) {
	var params []Param
	for !p.check(TokRParen) && !p.check(TokEOF) {
		nameTok, err := p.expect(TokIdent)
		if err != nil { return nil, err }
		if _, err := p.expect(TokColon); err != nil { return nil, err }
		t, err := p.parseType()
		if err != nil { return nil, err }
		params = append(params, Param{Name: nameTok.Lit, Type: t})
		if !p.eat(TokComma) { break }
	}
	return params, nil
}

// ----------------------------------------------------------------
// 타입 파싱
// ----------------------------------------------------------------

func (p *Parser) parseType() (*AstType, error) {
	tok := p.peek()
	switch tok.Kind {
	case TokI8:   p.advance(); return &AstType{Name: "i8"},  nil
	case TokI16:  p.advance(); return &AstType{Name: "i16"}, nil
	case TokI32:  p.advance(); return &AstType{Name: "i32"}, nil
	case TokI64:  p.advance(); return &AstType{Name: "i64"}, nil
	case TokU8:   p.advance(); return &AstType{Name: "u8"},  nil
	case TokU16:  p.advance(); return &AstType{Name: "u16"}, nil
	case TokU32:  p.advance(); return &AstType{Name: "u32"}, nil
	case TokU64:  p.advance(); return &AstType{Name: "u64"}, nil
	case TokF32:  p.advance(); return &AstType{Name: "f32"}, nil
	case TokF64:  p.advance(); return &AstType{Name: "f64"}, nil
	case TokBool: p.advance(); return &AstType{Name: "bool"},nil
	case TokVoid: p.advance(); return &AstType{Name: "void"},nil
	case TokStar: // *T → ptr<T>
		p.advance()
		inner, err := p.parseType()
		if err != nil { return nil, err }
		return &AstType{Name: "ptr", Inner: inner}, nil
	case TokIdent: // 사용자 정의 타입 (struct 이름 등, Phase 1에서는 통과)
		p.advance()
		return &AstType{Name: tok.Lit}, nil
	}
	return nil, fmt.Errorf("line %d: expected type, got %q", tok.Line, tok.Lit)
}

// ----------------------------------------------------------------
// Block (중괄호로 감싸진 문장 목록)
// ----------------------------------------------------------------

func (p *Parser) parseBlock() ([]*Stmt, error) {
	if _, err := p.expect(TokLBrace); err != nil { return nil, err }
	var stmts []*Stmt
	for !p.check(TokRBrace) && !p.check(TokEOF) {
		p.eat(TokSemi)
		if p.check(TokRBrace) { break }
		s, err := p.parseStmt()
		if err != nil { return nil, err }
		stmts = append(stmts, s)
		p.eat(TokSemi)
	}
	if _, err := p.expect(TokRBrace); err != nil { return nil, err }
	return stmts, nil
}

// ----------------------------------------------------------------
// 문장 파싱
// ----------------------------------------------------------------

func (p *Parser) parseStmt() (*Stmt, error) {
	tok := p.peek()

	switch tok.Kind {
	case TokLet:
		return p.parseLetStmt()
	case TokReturn:
		return p.parseReturnStmt()
	case TokIf:
		return p.parseIfStmt()
	case TokWhile:
		return p.parseWhileStmt()
	case TokIdent:
		// x = expr  또는  expr (함수 호출)
		if p.peek2().Kind == TokEq {
			return p.parseAssignStmt()
		}
		return p.parseExprStmt()
	default:
		return p.parseExprStmt()
	}
}

func (p *Parser) parseLetStmt() (*Stmt, error) {
	p.advance() // let
	isMut := p.eat(TokMut)

	nameTok, err := p.expect(TokIdent)
	if err != nil { return nil, err }

	var varType *AstType
	if p.eat(TokColon) {
		varType, err = p.parseType()
		if err != nil { return nil, err }
	}

	var init *Expr
	if p.eat(TokEq) {
		init, err = p.parseExpr()
		if err != nil { return nil, err }
	}

	return &Stmt{
		Kind: StmtLet, VarName: nameTok.Lit,
		VarType: varType, VarMut: isMut, Init: init,
	}, nil
}

func (p *Parser) parseAssignStmt() (*Stmt, error) {
	nameTok := p.advance() // ident
	p.advance()            // =
	val, err := p.parseExpr()
	if err != nil { return nil, err }
	return &Stmt{Kind: StmtAssign, Target: nameTok.Lit, Value: val}, nil
}

func (p *Parser) parseReturnStmt() (*Stmt, error) {
	p.advance() // return
	// return; 또는 return expr
	if p.check(TokRBrace) || p.check(TokSemi) || p.check(TokEOF) {
		return &Stmt{Kind: StmtReturn, RetVal: nil}, nil
	}
	val, err := p.parseExpr()
	if err != nil { return nil, err }
	return &Stmt{Kind: StmtReturn, RetVal: val}, nil
}

func (p *Parser) parseIfStmt() (*Stmt, error) {
	p.advance() // if
	cond, err := p.parseExpr()
	if err != nil { return nil, err }
	then, err := p.parseBlock()
	if err != nil { return nil, err }
	var els []*Stmt
	if p.eat(TokElse) {
		if p.check(TokIf) {
			// else if → 재귀
			inner, err := p.parseIfStmt()
			if err != nil { return nil, err }
			els = []*Stmt{inner}
		} else {
			els, err = p.parseBlock()
			if err != nil { return nil, err }
		}
	}
	return &Stmt{Kind: StmtIf, Cond: cond, Then: then, Else: els}, nil
}

func (p *Parser) parseWhileStmt() (*Stmt, error) {
	p.advance() // while
	cond, err := p.parseExpr()
	if err != nil { return nil, err }
	body, err := p.parseBlock()
	if err != nil { return nil, err }
	return &Stmt{Kind: StmtWhile, Cond: cond, Body: body}, nil
}

func (p *Parser) parseExprStmt() (*Stmt, error) {
	e, err := p.parseExpr()
	if err != nil { return nil, err }
	return &Stmt{Kind: StmtExpr, ExprVal: e}, nil
}

// ----------------------------------------------------------------
// 표현식 파싱 (Pratt / 우선순위 클라이밍)
// ----------------------------------------------------------------

func (p *Parser) parseExpr() (*Expr, error) {
	return p.parseOr()
}

func (p *Parser) parseOr() (*Expr, error) {
	left, err := p.parseAnd()
	if err != nil { return nil, err }
	for p.check(TokPipePipe) {
		p.advance()
		right, err := p.parseAnd()
		if err != nil { return nil, err }
		left = &Expr{Kind: ExprBinop, Op: "||", Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseAnd() (*Expr, error) {
	left, err := p.parseCmp()
	if err != nil { return nil, err }
	for p.check(TokAmpAmp) {
		p.advance()
		right, err := p.parseCmp()
		if err != nil { return nil, err }
		left = &Expr{Kind: ExprBinop, Op: "&&", Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseCmp() (*Expr, error) {
	left, err := p.parseBitOr()
	if err != nil { return nil, err }
	for {
		var op string
		switch p.peek().Kind {
		case TokEqEq:  op = "=="
		case TokBangEq:op = "!="
		case TokLt:    op = "<"
		case TokLtEq:  op = "<="
		case TokGt:    op = ">"
		case TokGtEq:  op = ">="
		default: return left, nil
		}
		p.advance()
		right, err := p.parseBitOr()
		if err != nil { return nil, err }
		left = &Expr{Kind: ExprBinop, Op: op, Left: left, Right: right}
	}
}

func (p *Parser) parseBitOr() (*Expr, error) {
	left, err := p.parseBitXor()
	if err != nil { return nil, err }
	for p.check(TokPipe) {
		p.advance()
		right, err := p.parseBitXor()
		if err != nil { return nil, err }
		left = &Expr{Kind: ExprBinop, Op: "|", Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseBitXor() (*Expr, error) {
	left, err := p.parseBitAnd()
	if err != nil { return nil, err }
	for p.check(TokCaret) {
		p.advance()
		right, err := p.parseBitAnd()
		if err != nil { return nil, err }
		left = &Expr{Kind: ExprBinop, Op: "^", Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseBitAnd() (*Expr, error) {
	left, err := p.parseShift()
	if err != nil { return nil, err }
	for p.check(TokAmp) {
		p.advance()
		right, err := p.parseShift()
		if err != nil { return nil, err }
		left = &Expr{Kind: ExprBinop, Op: "&", Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseShift() (*Expr, error) {
	left, err := p.parseAdd()
	if err != nil { return nil, err }
	for p.check(TokLtLt) || p.check(TokGtGt) {
		op := p.advance().Lit
		right, err := p.parseAdd()
		if err != nil { return nil, err }
		left = &Expr{Kind: ExprBinop, Op: op, Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseAdd() (*Expr, error) {
	left, err := p.parseMul()
	if err != nil { return nil, err }
	for p.check(TokPlus) || p.check(TokMinus) {
		op := p.advance().Lit
		right, err := p.parseMul()
		if err != nil { return nil, err }
		left = &Expr{Kind: ExprBinop, Op: op, Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseMul() (*Expr, error) {
	left, err := p.parseUnary()
	if err != nil { return nil, err }
	for p.check(TokStar) || p.check(TokSlash) || p.check(TokPercent) {
		op := p.advance().Lit
		right, err := p.parseUnary()
		if err != nil { return nil, err }
		left = &Expr{Kind: ExprBinop, Op: op, Left: left, Right: right}
	}
	return left, nil
}

func (p *Parser) parseUnary() (*Expr, error) {
	switch p.peek().Kind {
	case TokMinus:
		p.advance()
		operand, err := p.parseUnary()
		if err != nil { return nil, err }
		return &Expr{Kind: ExprUnary, Op: "-", Operand: operand}, nil
	case TokBang:
		p.advance()
		operand, err := p.parseUnary()
		if err != nil { return nil, err }
		return &Expr{Kind: ExprUnary, Op: "!", Operand: operand}, nil
	}
	return p.parsePrimary()
}

func (p *Parser) parsePrimary() (*Expr, error) {
	tok := p.peek()

	switch tok.Kind {
	case TokInt:
		p.advance()
		v, _ := strconv.ParseInt(tok.Lit, 10, 64)
		return &Expr{Kind: ExprInt, IVal: v}, nil

	case TokFloat:
		p.advance()
		v, _ := strconv.ParseFloat(tok.Lit, 64)
		return &Expr{Kind: ExprFloat, FVal: v}, nil

	case TokTrue:
		p.advance()
		return &Expr{Kind: ExprBool, BVal: true}, nil

	case TokFalse:
		p.advance()
		return &Expr{Kind: ExprBool, BVal: false}, nil

	case TokString:
		p.advance()
		return &Expr{Kind: ExprString, SVal: tok.Lit}, nil

	case TokIdent:
		name := tok.Lit
		p.advance()
		// 함수 호출: ident(args)
		if p.check(TokLParen) {
			p.advance()
			args, err := p.parseCallArgs()
			if err != nil { return nil, err }
			if _, err := p.expect(TokRParen); err != nil { return nil, err }
			return &Expr{Kind: ExprCall, Callee: name, Args: args}, nil
		}
		return &Expr{Kind: ExprIdent, SVal: name}, nil

	case TokLParen:
		p.advance()
		e, err := p.parseExpr()
		if err != nil { return nil, err }
		if _, err := p.expect(TokRParen); err != nil { return nil, err }
		return e, nil
	}

	return nil, fmt.Errorf("line %d: unexpected token %q in expression", tok.Line, tok.Lit)
}

func (p *Parser) parseCallArgs() ([]*Expr, error) {
	var args []*Expr
	for !p.check(TokRParen) && !p.check(TokEOF) {
		e, err := p.parseExpr()
		if err != nil { return nil, err }
		args = append(args, e)
		if !p.eat(TokComma) { break }
	}
	return args, nil
}

