// FreeLang → Free IR — IR Generator
// AST → ir.Module (SSA)
//
// 전략: mem2reg 없이 alloca+store+load로 모든 변수 처리
//       phi 노드 없음 (if/while은 alloca 기반)
//       → codegen Phase 1과 완전 호환
package irgen

import (
	"fmt"
	"fir/src/ir"
)

// ----------------------------------------------------------------
// 타입 변환: AstType → ir.Type
// ----------------------------------------------------------------

func astTypeToIR(t *AstType) *ir.Type {
	if t == nil { return ir.Void() }
	switch t.Name {
	case "i8":   return ir.I8()
	case "i16":  return ir.I16()
	case "i32":  return ir.I32()
	case "i64":  return ir.I64()
	case "u8":   return ir.U8()
	case "u16":  return ir.U16()
	case "u32":  return ir.U32()
	case "u64":  return ir.U64()
	case "f32":  return ir.F32()
	case "f64":  return ir.F64()
	case "bool": return ir.Bool()
	case "void": return ir.Void()
	case "ptr":
		if t.Inner != nil { return ir.Ptr(astTypeToIR(t.Inner)) }
		return ir.Ptr(ir.Void())
	}
	return ir.I64() // 기본: i64
}

// ----------------------------------------------------------------
// 함수 컴파일 컨텍스트
// ----------------------------------------------------------------

type fnCtx struct {
	mod      *ir.Module
	fn       *ir.Function
	blocks   []*ir.Block      // 완성된 블록들
	cur      *ir.Block        // 현재 블록
	locals   map[string]localVar  // 변수명 → {ptr reg, ir type}
	regCount int
	lblCount int
	retType  *ir.Type
	// extern 함수 시그니처 (call 타입 추론용)
	externSigs map[string]*ir.Type
	// 내부 함수 시그니처
	fnSigs map[string]*fnSig
}

type localVar struct {
	ptrReg string   // alloca 결과 (ptr)
	irType *ir.Type
}

type fnSig struct {
	params  []*ir.Type
	retType *ir.Type
}

func newFnCtx(mod *ir.Module, fn *ir.Function, retType *ir.Type,
	externSigs map[string]*ir.Type, fnSigs map[string]*fnSig) *fnCtx {
	entry := ir.NewBlock("entry")
	return &fnCtx{
		mod:       mod,
		fn:        fn,
		cur:       entry,
		locals:    make(map[string]localVar),
		retType:   retType,
		externSigs: externSigs,
		fnSigs:    fnSigs,
	}
}

func (c *fnCtx) newReg(prefix string) string {
	name := fmt.Sprintf("%s%d", prefix, c.regCount)
	c.regCount++
	return name
}

func (c *fnCtx) newLabel(prefix string) string {
	name := fmt.Sprintf("%s%d", prefix, c.lblCount)
	c.lblCount++
	return name
}

func (c *fnCtx) emit(inst *ir.Inst) {
	c.cur.Add(inst)
}

// 현재 블록 종료 후 새 블록 시작
func (c *fnCtx) startBlock(label string) {
	if !c.cur.IsTerminated() {
		// 암묵적 br (fallthrough)
		c.emit(ir.NewBr(label))
	}
	c.fn.AddBlock(c.cur)
	c.cur = ir.NewBlock(label)
}

// 현재 블록 강제 마무리
func (c *fnCtx) finishBlock() {
	c.fn.AddBlock(c.cur)
}

// ----------------------------------------------------------------
// 연산자 → IR op 매핑
// ----------------------------------------------------------------

func binopToIROp(op string, isFloat bool) string {
	if isFloat {
		switch op {
		case "+": return "fadd"
		case "-": return "fsub"
		case "*": return "fmul"
		case "/": return "fdiv"
		}
	}
	switch op {
	case "+": return "add"
	case "-": return "sub"
	case "*": return "mul"
	case "/": return "div"
	case "%": return "rem"
	case "&": return "and"
	case "|": return "or"
	case "^": return "xor"
	case "<<": return "shl"
	case ">>": return "shr"
	}
	return op
}

func cmpToIRPred(op string, isFloat bool) (string, bool) {
	if isFloat {
		switch op {
		case "==": return "oeq", true
		case "!=": return "one", true
		case "<":  return "olt", true
		case "<=": return "ole", true
		case ">":  return "ogt", true
		case ">=": return "oge", true
		}
	}
	switch op {
	case "==": return "eq",  false
	case "!=": return "ne",  false
	case "<":  return "lt",  false
	case "<=": return "le",  false
	case ">":  return "gt",  false
	case ">=": return "ge",  false
	}
	return "eq", false
}

// ----------------------------------------------------------------
// 표현식 컴파일 → *ir.Value
// ----------------------------------------------------------------

func (c *fnCtx) compileExpr(e *Expr) (*ir.Value, error) {
	switch e.Kind {

	case ExprInt:
		return ir.ConstInt(e.IVal, ir.I64()), nil

	case ExprFloat:
		return ir.ConstFloat(e.FVal, ir.F64()), nil

	case ExprBool:
		return ir.ConstBool(e.BVal), nil

	case ExprIdent:
		lv, ok := c.locals[e.SVal]
		if !ok {
			// 파라미터 레지스터로 직접 접근 (alloca 없이)
			return ir.Reg(e.SVal, ir.I64()), nil
		}
		res := c.newReg("v")
		c.emit(ir.NewLoad(res, lv.irType, ir.Reg(lv.ptrReg, ir.Ptr(lv.irType))))
		return ir.Reg(res, lv.irType), nil

	case ExprBinop:
		// 비교 연산자
		switch e.Op {
		case "==", "!=", "<", "<=", ">", ">=":
			lv, err := c.compileExpr(e.Left)
			if err != nil { return nil, err }
			rv, err := c.compileExpr(e.Right)
			if err != nil { return nil, err }
			isFloat := lv.Type != nil && (lv.Type.Kind == ir.TyF32 || lv.Type.Kind == ir.TyF64)
			pred, useF := cmpToIRPred(e.Op, isFloat)
			res := c.newReg("c")
			if useF {
				c.emit(ir.NewFCmp(pred, res, ir.F64(), lv, rv))
			} else {
				c.emit(ir.NewICmp(pred, res, lv.Type, lv, rv))
			}
			return ir.Reg(res, ir.Bool()), nil

		case "&&":
			// short-circuit: 스택 변수로 처리
			res := c.newReg("and")
			ptrName := res + "_ptr"
			c.emit(ir.NewAlloca(ptrName, ir.Bool()))
			c.emit(ir.NewStore(ir.Bool(), ir.ConstBool(false), ir.Reg(ptrName, ir.Ptr(ir.Bool()))))

			lblCheck := c.newLabel("and_check")
			lblEnd   := c.newLabel("and_end")

			lv, err := c.compileExpr(e.Left)
			if err != nil { return nil, err }
			c.emit(ir.NewBrCond(lv, lblCheck, lblEnd))
			c.startBlock(lblCheck)
			rv, err := c.compileExpr(e.Right)
			if err != nil { return nil, err }
			c.emit(ir.NewStore(ir.Bool(), rv, ir.Reg(ptrName, ir.Ptr(ir.Bool()))))
			c.startBlock(lblEnd)
			loaded := c.newReg("r")
			c.emit(ir.NewLoad(loaded, ir.Bool(), ir.Reg(ptrName, ir.Ptr(ir.Bool()))))
			return ir.Reg(loaded, ir.Bool()), nil

		case "||":
			res := c.newReg("or")
			ptrName := res + "_ptr"
			c.emit(ir.NewAlloca(ptrName, ir.Bool()))
			c.emit(ir.NewStore(ir.Bool(), ir.ConstBool(true), ir.Reg(ptrName, ir.Ptr(ir.Bool()))))

			lblCheck := c.newLabel("or_check")
			lblEnd   := c.newLabel("or_end")

			lv, err := c.compileExpr(e.Left)
			if err != nil { return nil, err }
			c.emit(ir.NewBrCond(lv, lblEnd, lblCheck))
			c.startBlock(lblCheck)
			rv, err := c.compileExpr(e.Right)
			if err != nil { return nil, err }
			c.emit(ir.NewStore(ir.Bool(), rv, ir.Reg(ptrName, ir.Ptr(ir.Bool()))))
			c.startBlock(lblEnd)
			loaded := c.newReg("r")
			c.emit(ir.NewLoad(loaded, ir.Bool(), ir.Reg(ptrName, ir.Ptr(ir.Bool()))))
			return ir.Reg(loaded, ir.Bool()), nil
		}

		// 산술 연산
		lv, err := c.compileExpr(e.Left)
		if err != nil { return nil, err }
		rv, err := c.compileExpr(e.Right)
		if err != nil { return nil, err }
		isFloat := lv.Type != nil && (lv.Type.Kind == ir.TyF32 || lv.Type.Kind == ir.TyF64)
		op := binopToIROp(e.Op, isFloat)
		res := c.newReg("r")
		t := lv.Type
		if t == nil { t = ir.I64() }
		c.emit(ir.NewBinop(op, res, t, lv, rv))
		return ir.Reg(res, t), nil

	case ExprUnary:
		switch e.Op {
		case "-":
			v, err := c.compileExpr(e.Operand)
			if err != nil { return nil, err }
			res := c.newReg("neg")
			t := v.Type
			if t == nil { t = ir.I64() }
			c.emit(ir.NewBinop("sub", res, t, ir.ConstInt(0, t), v))
			return ir.Reg(res, t), nil
		case "!":
			v, err := c.compileExpr(e.Operand)
			if err != nil { return nil, err }
			res := c.newReg("not")
			c.emit(ir.NewICmp("eq", res, ir.Bool(), v, ir.ConstInt(0, ir.Bool())))
			return ir.Reg(res, ir.Bool()), nil
		}

	case ExprCall:
		args := make([]*ir.Value, len(e.Args))
		for i, a := range e.Args {
			v, err := c.compileExpr(a)
			if err != nil { return nil, err }
			args[i] = v
		}
		// 반환 타입 결정
		var retT *ir.Type
		if sig, ok := c.fnSigs[e.Callee]; ok {
			retT = sig.retType
		} else if t, ok := c.externSigs[e.Callee]; ok {
			retT = t
		} else {
			retT = ir.I64() // 기본
		}
		callee := ir.GlobalRef(e.Callee, retT)
		if retT.Kind == ir.TyVoid {
			c.emit(ir.NewCall("", retT, callee, args))
			return ir.ConstInt(0, ir.I64()), nil
		}
		res := c.newReg("ret")
		c.emit(ir.NewCall(res, retT, callee, args))
		return ir.Reg(res, retT), nil
	}

	return nil, fmt.Errorf("unsupported expr kind %d", e.Kind)
}

// ----------------------------------------------------------------
// 문장 컴파일
// ----------------------------------------------------------------

func (c *fnCtx) compileStmt(s *Stmt) error {
	switch s.Kind {

	case StmtLet:
		irType := ir.I64()
		if s.VarType != nil { irType = astTypeToIR(s.VarType) }

		// alloca
		ptrName := s.VarName + "_ptr"
		c.emit(ir.NewAlloca(ptrName, irType))
		c.locals[s.VarName] = localVar{ptrReg: ptrName, irType: irType}

		// 초기화
		if s.Init != nil {
			val, err := c.compileExpr(s.Init)
			if err != nil { return err }
			c.emit(ir.NewStore(irType, val, ir.Reg(ptrName, ir.Ptr(irType))))
		}
		return nil

	case StmtAssign:
		lv, ok := c.locals[s.Target]
		if !ok {
			return fmt.Errorf("undefined variable: %s", s.Target)
		}
		val, err := c.compileExpr(s.Value)
		if err != nil { return err }
		c.emit(ir.NewStore(lv.irType, val, ir.Reg(lv.ptrReg, ir.Ptr(lv.irType))))
		return nil

	case StmtReturn:
		if s.RetVal == nil || c.retType.Kind == ir.TyVoid {
			c.emit(ir.NewRetVoid())
		} else {
			val, err := c.compileExpr(s.RetVal)
			if err != nil { return err }
			c.emit(ir.NewRet(val))
		}
		return nil

	case StmtIf:
		lblThen := c.newLabel("if_then")
		lblElse := c.newLabel("if_else")
		lblEnd  := c.newLabel("if_end")

		cond, err := c.compileExpr(s.Cond)
		if err != nil { return err }

		if len(s.Else) > 0 {
			c.emit(ir.NewBrCond(cond, lblThen, lblElse))
		} else {
			c.emit(ir.NewBrCond(cond, lblThen, lblEnd))
		}

		// then
		c.startBlock(lblThen)
		for _, st := range s.Then {
			if err := c.compileStmt(st); err != nil { return err }
		}
		if !c.cur.IsTerminated() {
			c.emit(ir.NewBr(lblEnd))
		}

		// else
		if len(s.Else) > 0 {
			c.startBlock(lblElse)
			for _, st := range s.Else {
				if err := c.compileStmt(st); err != nil { return err }
			}
			if !c.cur.IsTerminated() {
				c.emit(ir.NewBr(lblEnd))
			}
		}

		c.startBlock(lblEnd)
		return nil

	case StmtWhile:
		lblCond := c.newLabel("while_cond")
		lblBody := c.newLabel("while_body")
		lblEnd  := c.newLabel("while_end")

		c.emit(ir.NewBr(lblCond))
		c.startBlock(lblCond)

		cond, err := c.compileExpr(s.Cond)
		if err != nil { return err }
		c.emit(ir.NewBrCond(cond, lblBody, lblEnd))

		c.startBlock(lblBody)
		for _, st := range s.Body {
			if err := c.compileStmt(st); err != nil { return err }
		}
		if !c.cur.IsTerminated() {
			c.emit(ir.NewBr(lblCond))
		}

		c.startBlock(lblEnd)
		return nil

	case StmtExpr:
		_, err := c.compileExpr(s.ExprVal)
		return err
	}

	return nil
}

// ----------------------------------------------------------------
// 함수 컴파일
// ----------------------------------------------------------------

func compileFn(mod *ir.Module, decl *FnDecl,
	externSigs map[string]*ir.Type, fnSigs map[string]*fnSig) error {

	retType := astTypeToIR(decl.RetType)
	params := make([]ir.Param, len(decl.Params))
	for i, p := range decl.Params {
		params[i] = ir.Param{Name: p.Name, Type: astTypeToIR(p.Type)}
	}

	fn := ir.NewFunction(decl.Name, params, retType, false)
	ctx := newFnCtx(mod, fn, retType, externSigs, fnSigs)

	// 파라미터를 alloca+store로 내림 (SSA 단순화)
	for _, p := range decl.Params {
		irT := astTypeToIR(p.Type)
		ptrName := p.Name + "_ptr"
		ctx.emit(ir.NewAlloca(ptrName, irT))
		ctx.emit(ir.NewStore(irT, ir.Reg(p.Name, irT), ir.Reg(ptrName, ir.Ptr(irT))))
		ctx.locals[p.Name] = localVar{ptrReg: ptrName, irType: irT}
	}

	for _, s := range decl.Body {
		if err := ctx.compileStmt(s); err != nil { return err }
	}

	// 함수 끝에 암묵적 ret void
	if !ctx.cur.IsTerminated() {
		if retType.Kind == ir.TyVoid {
			ctx.emit(ir.NewRetVoid())
		} else {
			ctx.emit(ir.NewRet(ir.ConstInt(0, retType)))
		}
	}
	ctx.finishBlock()
	mod.AddFunction(fn)
	return nil
}

// ----------------------------------------------------------------
// 모듈 컴파일 (진입점)
// ----------------------------------------------------------------

func Compile(src string) (*ir.Module, error) {
	prog, err := ParseProgram(src)
	if err != nil { return nil, fmt.Errorf("parse: %w", err) }
	return CompileProgram(prog)
}

func CompileProgram(prog *Program) (*ir.Module, error) {
	mod := ir.NewModule("fl")

	// 1패스: 시그니처 수집
	externSigs := make(map[string]*ir.Type)
	fnSigs     := make(map[string]*fnSig)

	for _, decl := range prog.Fns {
		retT := astTypeToIR(decl.RetType)
		paramTs := make([]*ir.Type, len(decl.Params))
		for i, p := range decl.Params { paramTs[i] = astTypeToIR(p.Type) }

		if decl.IsExtern {
			externSigs[decl.Name] = retT
			ext := &ir.ExternFunction{
				Name: decl.Name, ParamTypes: paramTs, RetType: retT,
			}
			mod.AddExtern(ext)
		} else {
			fnSigs[decl.Name] = &fnSig{params: paramTs, retType: retT}
		}
	}

	// 2패스: 함수 바디 컴파일
	for _, decl := range prog.Fns {
		if decl.IsExtern { continue }
		if err := compileFn(mod, decl, externSigs, fnSigs); err != nil {
			return nil, fmt.Errorf("fn %s: %w", decl.Name, err)
		}
	}

	return mod, nil
}

