// FreeLang → IR 컴파일러 검증
// FL 소스 → IR → interp + native 실행
package main

import (
	"fmt"
	"fir/src/codegen"
	"fir/src/interp"
	"fir/src/irgen"
)

var flPassed, flFailed int

// FL 소스 → interp 실행 결과 검증
func assertFL(label, src, fnName string, args []interp.RVal, expected int64) {
	mod, err := irgen.Compile(src)
	if err != nil {
		fmt.Printf("[FAIL] %s | parse/irgen: %v\n", label, err)
		flFailed++
		return
	}

	r, err := interp.ExecModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | interp: %v\n", label, err)
		flFailed++
		return
	}

	if r.AsInt() == expected {
		fmt.Printf("[PASS] %s\n", label)
		flPassed++
	} else {
		fmt.Printf("[FAIL] %s | got=%d expected=%d\n", label, r.AsInt(), expected)
		flFailed++
		// IR 덤프 (디버그용)
		fmt.Println("  IR:")
		for _, line := range splitLines(mod.String()) {
			fmt.Println("  " + line)
		}
	}
}

// FL 소스 → interp + native 동시 검증
func assertFLNative(label, src, fnName string, args []interp.RVal, expected int64) {
	mod, err := irgen.Compile(src)
	if err != nil {
		fmt.Printf("[FAIL] %s | parse/irgen: %v\n", label, err)
		flFailed++
		return
	}

	// interp
	ir_r, err := interp.ExecModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | interp: %v\n", label, err)
		flFailed++
		return
	}
	interpVal := ir_r.AsInt()

	// native (main 함수로 감쌈)
	cm, err := codegen.CompileModule(mod)
	if err != nil {
		fmt.Printf("[FAIL] %s | codegen: %v\n", label, err)
		flFailed++
		return
	}
	off, ok := cm.FuncOff[fnName]
	if !ok {
		fmt.Printf("[FAIL] %s | fn not found: %s\n", label, fnName)
		flFailed++
		return
	}
	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
	nativeVal, err := execElf(elfBytes)
	if err != nil {
		// native 실행 불가 (ARM64 + qemu 없는 경우) → interp만 검증
		if interpVal == expected {
			fmt.Printf("[PASS] %s (interp only)\n", label)
			flPassed++
		} else {
			fmt.Printf("[FAIL] %s | interp=%d expected=%d\n", label, interpVal, expected)
			flFailed++
		}
		return
	}

	if interpVal == expected && nativeVal == expected {
		fmt.Printf("[PASS] %s | interp=%d native=%d\n", label, interpVal, nativeVal)
		flPassed++
	} else {
		fmt.Printf("[FAIL] %s | interp=%d native=%d expected=%d\n",
			label, interpVal, nativeVal, expected)
		flFailed++
	}
}

func splitLines(s string) []string {
	var lines []string
	cur := ""
	for _, ch := range s {
		if ch == '\n' { lines = append(lines, cur); cur = "" } else { cur += string(ch) }
	}
	if cur != "" { lines = append(lines, cur) }
	return lines
}

// ----------------------------------------------------------------
// 테스트 케이스
// ----------------------------------------------------------------

func runIRGenTests() {
	fmt.Println()
	fmt.Println("=== IRGen Tests (FL → IR) ===")

	// ── Test FL-1: 상수 반환 ──
	assertFLNative("FL-1: const return",
		`fn answer() -> i64 { return 42 }`,
		"answer", nil, 42)

	// ── Test FL-2: 덧셈 ──
	assertFLNative("FL-2: add",
		`fn add(a: i64, b: i64) -> i64 { return a + b }`,
		"add", []interp.RVal{interp.RInt(10), interp.RInt(32)}, 42)

	// ── Test FL-3: 뺄셈/곱셈 ──
	assertFL("FL-3: mul",
		`fn mul(a: i64, b: i64) -> i64 { return a * b }`,
		"mul", []interp.RVal{interp.RInt(6), interp.RInt(7)}, 42)

	// ── Test FL-4: 조건 분기 ──
	assertFL("FL-4: if/else (true branch)",
		`fn is_pos(x: i64) -> i64 {
			if x > 0 {
				return 1
			} else {
				return 0
			}
		}`,
		"is_pos", []interp.RVal{interp.RInt(5)}, 1)

	assertFL("FL-4: if/else (false branch)",
		`fn is_pos(x: i64) -> i64 {
			if x > 0 {
				return 1
			} else {
				return 0
			}
		}`,
		"is_pos", []interp.RVal{interp.RInt(-3)}, 0)

	// ── Test FL-5: let 변수 ──
	assertFL("FL-5: let var",
		`fn compute() -> i64 {
			let x: i64 = 10
			let y: i64 = 32
			return x + y
		}`,
		"compute", nil, 42)

	// ── Test FL-6: while 루프 (0..n 합산) ──
	assertFL("FL-6: while sum(5)=10",
		`fn sum(n: i64) -> i64 {
			let s: i64 = 0
			let i: i64 = 0
			while i < n {
				s = s + i
				i = i + 1
			}
			return s
		}`,
		"sum", []interp.RVal{interp.RInt(5)}, 10)

	assertFL("FL-6: while sum(10)=45",
		`fn sum(n: i64) -> i64 {
			let s: i64 = 0
			let i: i64 = 0
			while i < n {
				s = s + i
				i = i + 1
			}
			return s
		}`,
		"sum", []interp.RVal{interp.RInt(10)}, 45)

	// ── Test FL-7: 재귀 (factorial) ──
	assertFL("FL-7: factorial(5)=120",
		`fn factorial(n: i64) -> i64 {
			if n <= 1 {
				return 1
			}
			return n * factorial(n - 1)
		}`,
		"factorial", []interp.RVal{interp.RInt(5)}, 120)

	// ── Test FL-8: 다중 함수 호출 ──
	assertFL("FL-8: multi-fn quad(3)=12",
		`fn double(x: i64) -> i64 { return x * 2 }
		fn quad(x: i64) -> i64 { return double(double(x)) }`,
		"quad", []interp.RVal{interp.RInt(3)}, 12)

	// ── Test FL-9: else if 체인 ──
	assertFL("FL-9: else if (cmp>0)",
		`fn sign(x: i64) -> i64 {
			if x > 0 {
				return 1
			} else if x < 0 {
				return -1
			} else {
				return 0
			}
		}`,
		"sign", []interp.RVal{interp.RInt(5)}, 1)

	assertFL("FL-9: else if (cmp<0)",
		`fn sign(x: i64) -> i64 {
			if x > 0 {
				return 1
			} else if x < 0 {
				return -1
			} else {
				return 0
			}
		}`,
		"sign", []interp.RVal{interp.RInt(-3)}, -1)

	assertFL("FL-9: else if (zero)",
		`fn sign(x: i64) -> i64 {
			if x > 0 {
				return 1
			} else if x < 0 {
				return -1
			} else {
				return 0
			}
		}`,
		"sign", []interp.RVal{interp.RInt(0)}, 0)

	// ── Test FL-10: div/rem ──
	assertFL("FL-10: div 20/4=5",
		`fn div(a: i64, b: i64) -> i64 { return a / b }`,
		"div", []interp.RVal{interp.RInt(20), interp.RInt(4)}, 5)

	assertFL("FL-10: rem 10%3=1",
		`fn rem(a: i64, b: i64) -> i64 { return a % b }`,
		"rem", []interp.RVal{interp.RInt(10), interp.RInt(3)}, 1)

	// ── Test FL-11: IR 텍스트 출력 ──
	fmt.Println("--- FL-11: IR text output ---")
	src := `fn inc(x: i64) -> i64 { return x + 1 }`
	mod, err := irgen.Compile(src)
	if err != nil {
		fmt.Printf("[FAIL] FL-11: %v\n", err)
		flFailed++
	} else {
		text := mod.String()
		if len(text) > 0 {
			fmt.Println(text)
			fmt.Println("[PASS] FL-11: IR text output")
			flPassed++
		} else {
			fmt.Println("[FAIL] FL-11: empty IR")
			flFailed++
		}
	}

	fmt.Println()
	fmt.Printf("IRGen Results: %d/%d PASS\n", flPassed, flPassed+flFailed)
	if flFailed == 0 {
		fmt.Println()
		fmt.Println("FL → IR → INTERP/NATIVE VERIFIED")
		fmt.Println("FreeLang is a Free IR frontend.")
	}
}

