// FL 소스 → interp + native 동시 검증
// args가 있으면 FL 소스에 __main_wrap 함수를 추가해 상수 인자로 호출
func assertFLNative(label, src, fnName string, args []interp.RVal, expected int64) {
	mod, err := irgen.Compile(src)
	if err != nil {
		fmt.Printf("[FAIL] %s | parse/irgen: %v\n", label, err)
		flFailed++
		return
	}

	// interp
	ir_r, err := interp.ExecModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | interp: %v\n", label, err)
		flFailed++
		return
	}
	interpVal := ir_r.AsInt()

	// native: 인자가 있으면 래퍼 생성
	nativeEntry := fnName
	if len(args) > 0 {
		// __wrap 함수: 상수 인자로 fnName 호출 후 결과 반환
		wrapSrc := src + "\n" + buildWrapFn(fnName, args)
		mod2, err2 := irgen.Compile(wrapSrc)
		if err2 != nil {
			fmt.Printf("[FAIL] %s | wrap codegen: %v\n", label, err2)
			flFailed++
			return
		}
		mod = mod2
		nativeEntry = "__wrap"
	}

	cm, err := codegen.CompileModule(mod)
	if err != nil {
		fmt.Printf("[FAIL] %s | codegen: %v\n", label, err)
		flFailed++
		return
	}
	off, ok := cm.FuncOff[nativeEntry]
	if !ok {
		fmt.Printf("[FAIL] %s | fn not found: %s\n", label, nativeEntry)
		flFailed++
		return
	}
	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
	nativeVal, err := execElf(elfBytes)
	if err != nil {
		if interpVal == expected {
			fmt.Printf("[PASS] %s (interp only)\n", label)
			flPassed++
		} else {
			fmt.Printf("[FAIL] %s | interp=%d expected=%d\n", label, interpVal, expected)
			flFailed++
		}
		return
	}

	if interpVal == expected && nativeVal == expected {
		fmt.Printf("[PASS] %s | interp=%d native=%d\n", label, interpVal, nativeVal)
		flPassed++
	} else {
		fmt.Printf("[FAIL] %s | interp=%d native=%d expected=%d\n",
			label, interpVal, nativeVal, expected)
		flFailed++
	}
}

// buildWrapFn: fnName(args...) 를 상수 인자로 호출하는 래퍼 FL 코드 생성
func buildWrapFn(fnName string, args []interp.RVal) string {
	s := "fn __wrap() -> i64 { return " + fnName + "("
	for i, a := range args {
		if i > 0 { s += ", " }
		s += fmt.Sprintf("%d", a.AsInt())
	}
	s += ") }"
	return s
}

