// FreeLang → IR 컴파일러 검증
// FL 소스 → IR → interp + native 실행
package main

import (
	"fmt"
	"fir/src/codegen"
	"fir/src/interp"
	"fir/src/irgen"
)

var flPassed, flFailed int

// FL 소스 → interp 실행 결과 검증
func assertFL(label, src, fnName string, args []interp.RVal, expected int64) {
	mod, err := irgen.Compile(src)
	if err != nil {
		fmt.Printf("[FAIL] %s | parse/irgen: %v\n", label, err)
		flFailed++
		return
	}

	r, err := interp.ExecModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | interp: %v\n", label, err)
		flFailed++
		return
	}

	if r.AsInt() == expected {
		fmt.Printf("[PASS] %s\n", label)
		flPassed++
	} else {
		fmt.Printf("[FAIL] %s | got=%d expected=%d\n", label, r.AsInt(), expected)
		flFailed++
		// IR 덤프 (디버그용)
		fmt.Println("  IR:")
		for _, line := range splitLines(mod.String()) {
			fmt.Println("  " + line)
		}
	}
}

// FL 소스 → interp + native 동시 검증
func assertFLNative(label, src, fnName string, args []interp.RVal, expected int64) {
	mod, err := irgen.Compile(src)
	if err != nil {
		fmt.Printf("[FAIL] %s | parse/irgen: %v\n", label, err)
		flFailed++
		return
	}

	// interp
	ir_r, err := interp.ExecModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | interp: %v\n", label, err)
		flFailed++
		return
	}
	interpVal := ir_r.AsInt()

	// native (main 함수로 감쌈)
	cm, err := codegen.CompileModule(mod)
	if err != nil {
		fmt.Printf("[FAIL] %s | codegen: %v\n", label, err)
		flFailed++
		return
	}
	off, ok := cm.FuncOff[fnName]
	if !ok {
		fmt.Printf("[FAIL] %s | fn not found: %s\n", label, fnName)
		flFailed++
		return
	}
	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
	nativeVal, err := execElf(elfBytes)
	if err != nil {
		// native 실행 불가 (ARM64 + qemu 없는 경우) → interp만 검증
		if interpVal == expected {
			fmt.Printf("[PASS] %s (interp only)\n", label)
			flPassed++
		} else {
			fmt.Printf("[FAIL] %s | interp=%d expected=%d\n", label, interpVal, expected)
			flFailed++
		}
		return
	}

	if interpVal == expected && nativeVal == expected {
		fmt.Printf("[PASS] %s | interp=%d native=%d\n", label, interpVal, nativeVal)
		flPassed++
	} else {
		fmt.Printf("[FAIL] %s | interp=%d native=%d expected=%d\n",
			label, interpVal, nativeVal, expected)
		flFailed++
	}
}

func splitLines(s string) []string {
	var lines []string
	cur := ""
	for _, ch := range s {
		if ch == '\n' { lines = append(lines, cur); cur = "" } else { cur += string(ch) }
	}
	if cur != "" { lines = append(lines, cur) }
	return lines
}

